package com.josiahcooper.miningstats;

import org.junit.Test;

import java.util.Optional;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * v0.2.0 session-persistence audit: serialize and parse {@link RollingWindow.Snapshot}
 * cleanly across an OSRS client disconnect/reconnect cycle.
 *
 * <p>The {@link RollingWindow} round-trip test is the load-bearing one — it verifies that a
 * restored window produces the same rate calculation as the original, which is the user-
 * visible contract of the persistence layer.
 */
public class SessionPersistenceTest
{
	private static final int COPPER = 436;
	private static final int IRON = 440;

	private static RollingWindow buildWindow()
	{
		// 30-second AFK threshold matches the config default.
		RollingWindow w = new RollingWindow(30_000L);
		long t0 = 1_700_000_000_000L;
		w.recordEvent(COPPER, t0);
		w.recordEvent(COPPER, t0 + 5_000);
		w.recordEvent(IRON, t0 + 12_000);
		w.recordEvent(COPPER, t0 + 20_000);
		return w;
	}

	@Test
	public void roundTrip_preservesAllStateAndRateCalculation()
	{
		RollingWindow original = buildWindow();
		long now = 1_700_000_030_000L;
		double originalRate = original.activeRatePerHour(60_000L, now);

		String serialized = SessionPersistence.serialize(original.exportSnapshot(), now);
		assertNotNull("serialize should produce non-null for a populated window", serialized);

		Optional<RollingWindow.Snapshot> parsed = SessionPersistence.parse(
			serialized, now + 60_000L, SessionPersistence.DEFAULT_MAX_AGE_MS);
		assertTrue(parsed.isPresent());

		RollingWindow restored = new RollingWindow(30_000L);
		restored.restoreFromSnapshot(parsed.get());

		assertEquals(original.totalCount(), restored.totalCount());
		assertEquals(original.totalCount(COPPER), restored.totalCount(COPPER));
		assertEquals(original.totalCount(IRON), restored.totalCount(IRON));
		// Rate computed at the same nowWallMs should match — the load-bearing user-visible contract.
		assertEquals(originalRate, restored.activeRatePerHour(60_000L, now), 0.001);
	}

	@Test
	public void roundTrip_preservesEventOrderForPrune()
	{
		// RollingWindow.prune() relies on insertion order (early-out break on first non-stale event).
		// If serialize/parse reorders, prune behavior breaks — even if all rate math still works
		// initially, subsequent recordEvent calls can leave stale events in the deque.
		RollingWindow original = buildWindow();
		long now = 1_700_000_030_000L;
		String serialized = SessionPersistence.serialize(original.exportSnapshot(), now);
		Optional<RollingWindow.Snapshot> parsed = SessionPersistence.parse(
			serialized, now, SessionPersistence.DEFAULT_MAX_AGE_MS);
		assertTrue(parsed.isPresent());

		long prevActive = -1L;
		for (RollingWindow.EventData e : parsed.get().events)
		{
			assertTrue("activeTimeMs must be non-decreasing in parsed order", e.activeTimeMs >= prevActive);
			prevActive = e.activeTimeMs;
		}
	}

	@Test
	public void parse_nullOrEmptyText_returnsEmpty()
	{
		assertFalse(SessionPersistence.parse(null, 0L, SessionPersistence.DEFAULT_MAX_AGE_MS).isPresent());
		assertFalse(SessionPersistence.parse("", 0L, SessionPersistence.DEFAULT_MAX_AGE_MS).isPresent());
	}

	@Test
	public void parse_staleSnapshot_returnsEmpty()
	{
		// Build a real snapshot, then parse with nowWallMs far in the future.
		RollingWindow w = buildWindow();
		long snapTime = 1_700_000_030_000L;
		String serialized = SessionPersistence.serialize(w.exportSnapshot(), snapTime);
		long farFuture = snapTime + SessionPersistence.DEFAULT_MAX_AGE_MS + 1;
		assertFalse(SessionPersistence.parse(serialized, farFuture, SessionPersistence.DEFAULT_MAX_AGE_MS).isPresent());
	}

	@Test
	public void parse_freshSnapshotJustInsideMaxAge_succeeds()
	{
		// Boundary case: snapshot exactly at maxAge should still load (cutoff is strict >).
		RollingWindow w = buildWindow();
		long snapTime = 1_700_000_030_000L;
		String serialized = SessionPersistence.serialize(w.exportSnapshot(), snapTime);
		long edgeOfWindow = snapTime + SessionPersistence.DEFAULT_MAX_AGE_MS;
		assertTrue(SessionPersistence.parse(serialized, edgeOfWindow, SessionPersistence.DEFAULT_MAX_AGE_MS).isPresent());
	}

	@Test
	public void parse_wrongVersion_returnsEmpty()
	{
		String serialized = "v=99;snap=0;cum=0;last=0;tot=0";
		assertFalse(SessionPersistence.parse(serialized, 0L, SessionPersistence.DEFAULT_MAX_AGE_MS).isPresent());
	}

	@Test
	public void parse_missingVersionHeader_returnsEmpty()
	{
		String serialized = "snap=0;cum=0;last=0;tot=0";
		assertFalse(SessionPersistence.parse(serialized, 0L, SessionPersistence.DEFAULT_MAX_AGE_MS).isPresent());
	}

	@Test
	public void parse_missingRequiredField_returnsEmpty()
	{
		// Missing 'tot' → reject. (Version present, but header incomplete.)
		String serialized = "v=1;snap=0;cum=0;last=0";
		assertFalse(SessionPersistence.parse(serialized, 0L, SessionPersistence.DEFAULT_MAX_AGE_MS).isPresent());
	}

	@Test
	public void parse_malformedEventRecord_returnsEmpty()
	{
		// 'e' record with only 2 fields instead of 3.
		String serialized = "v=1;snap=0;cum=0;last=0;tot=1;e=436,1000";
		assertFalse(SessionPersistence.parse(serialized, 0L, SessionPersistence.DEFAULT_MAX_AGE_MS).isPresent());
	}

	@Test
	public void parse_nonNumericField_returnsEmpty()
	{
		String serialized = "v=1;snap=NOT_A_NUMBER;cum=0;last=0;tot=0";
		assertFalse(SessionPersistence.parse(serialized, 0L, SessionPersistence.DEFAULT_MAX_AGE_MS).isPresent());
	}

	@Test
	public void parse_unknownKey_skippedForForwardCompat()
	{
		// Future format may add fields. Older parsers must not reject.
		String serialized = "v=1;snap=0;cum=0;last=0;tot=0;futurefield=anything";
		Optional<RollingWindow.Snapshot> parsed = SessionPersistence.parse(
			serialized, 0L, SessionPersistence.DEFAULT_MAX_AGE_MS);
		assertTrue(parsed.isPresent());
	}

	@Test
	public void serialize_emptySession_returnsNull()
	{
		// sessionTotal == 0 means nothing worth persisting.
		RollingWindow empty = new RollingWindow(30_000L);
		assertNull(SessionPersistence.serialize(empty.exportSnapshot(), 1_700_000_000_000L));
	}

	@Test
	public void serialize_nullSnapshot_returnsNull()
	{
		assertNull(SessionPersistence.serialize(null, 1_700_000_000_000L));
	}

	@Test
	public void roundTrip_throughDisconnectScenario_continuesSession()
	{
		// Simulates the user-visible failure mode the audit was scoped to fix:
		// 1. Player mines for a while, accumulating events.
		// 2. Client disconnects (we serialize at this moment).
		// 3. Player reconnects 5 minutes later (well within MAX_AGE).
		// 4. We restore and continue mining — the resumed session's rate should reflect
		//    pre-disconnect events, not start from zero.
		RollingWindow before = buildWindow();
		long disconnectTime = 1_700_000_030_000L;
		String blob = SessionPersistence.serialize(before.exportSnapshot(), disconnectTime);

		long reconnectTime = disconnectTime + 5L * 60_000L; // 5 min later
		Optional<RollingWindow.Snapshot> snap = SessionPersistence.parse(
			blob, reconnectTime, SessionPersistence.DEFAULT_MAX_AGE_MS);
		assertTrue(snap.isPresent());

		RollingWindow after = new RollingWindow(30_000L);
		after.restoreFromSnapshot(snap.get());
		// Continue mining — record one more event.
		after.recordEvent(COPPER, reconnectTime + 1_000L);

		assertEquals("session totals carry across the disconnect", 5, after.totalCount());
		assertEquals(3 + 1, after.totalCount(COPPER));
		assertEquals(1, after.totalCount(IRON));
	}
}

package com.josiahcooper.miningstats;

import org.junit.Test;

import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

public class RollingWindowTest
{
	private static final long AFK_30S = 30_000L;
	private static final long ONE_MIN = 60_000L;
	private static final long FIVE_MIN = 5 * ONE_MIN;

	private static final int COPPER = 436;
	private static final int IRON = 440;

	@Test
	public void emptyWindowReportsZero()
	{
		RollingWindow w = new RollingWindow(AFK_30S);
		assertEquals(0.0, w.activeRatePerHour(FIVE_MIN, 0L), 0.0001);
		assertEquals(0, w.totalCount());
	}

	@Test
	public void steadyMiningProducesExpectedRate()
	{
		// 30 events spaced 10s apart. After the 30th event: 29 gaps × 10s = 290s of active time.
		// Window = 5 min, capped to 290s. Rate = 30 events / 290s × 3600 ≈ 372.4/hr.
		RollingWindow w = new RollingWindow(AFK_30S);
		long t = 0L;
		for (int i = 0; i < 30; i++)
		{
			t += 10_000L;
			w.recordEvent(COPPER, t);
		}
		double rate = w.activeRatePerHour(FIVE_MIN, t);
		assertEquals(372.4, rate, 1.0);
		assertEquals(30, w.totalCount());
	}

	@Test
	public void afkGapDoesNotDilateRate()
	{
		// Mine 4 events at 10s intervals, AFK 10 minutes, then mine 1 more.
		// Active time = 30s (the 3 gaps inside the first burst). Post-AFK gap > threshold → contributes 0.
		// 5 events / 30s × 3600 = 600/hr — i.e., the AFK didn't drag the rate down.
		RollingWindow w = new RollingWindow(AFK_30S);
		long t = 0L;
		for (int i = 0; i < 4; i++)
		{
			t += 10_000L;
			w.recordEvent(COPPER, t);
		}
		t += 10 * ONE_MIN; // AFK
		w.recordEvent(COPPER, t);
		double rate = w.activeRatePerHour(FIVE_MIN, t);
		assertEquals(600.0, rate, 0.5);
	}

	@Test
	public void perOreRateSeparation()
	{
		// 10 copper @ 6s spacing, then 5 iron @ 6s spacing. 14 gaps of 6s = 84s active.
		RollingWindow w = new RollingWindow(AFK_30S);
		long t = 0L;
		for (int i = 0; i < 10; i++) { t += 6_000L; w.recordEvent(COPPER, t); }
		for (int i = 0; i < 5; i++)  { t += 6_000L; w.recordEvent(IRON,   t); }
		double copperRate = w.activeRatePerHour(COPPER, FIVE_MIN, t);
		double ironRate   = w.activeRatePerHour(IRON,   FIVE_MIN, t);
		// 10 / 84s × 3600 ≈ 428.6;  5 / 84s × 3600 ≈ 214.3
		assertEquals(428.6, copperRate, 1.0);
		assertEquals(214.3, ironRate,   1.0);
	}

	@Test
	public void totalByOreSortedDescending()
	{
		RollingWindow w = new RollingWindow(AFK_30S);
		long t = 0L;
		for (int i = 0; i < 3; i++) { t += 5_000L; w.recordEvent(IRON,   t); }
		for (int i = 0; i < 7; i++) { t += 5_000L; w.recordEvent(COPPER, t); }
		Map<Integer, Integer> totals = w.totalByOre();
		assertEquals(Integer.valueOf(COPPER), totals.keySet().iterator().next());
		assertEquals(7, totals.get(COPPER).intValue());
		assertEquals(3, totals.get(IRON).intValue());
	}

	@Test
	public void rejectsNonPositiveAfkThreshold()
	{
		try
		{
			new RollingWindow(0L);
			fail("Expected IllegalArgumentException");
		}
		catch (IllegalArgumentException expected)
		{
			assertTrue(true);
		}
	}

	@Test
	public void clearResetsState()
	{
		RollingWindow w = new RollingWindow(AFK_30S);
		w.recordEvent(COPPER, 1_000L);
		w.recordEvent(COPPER, 2_000L);
		assertEquals(2, w.totalCount());
		w.clear();
		assertEquals(0, w.totalCount());
		assertEquals(0.0, w.activeRatePerHour(FIVE_MIN, 3_000L), 0.0001);
	}

	@Test
	public void shortSessionUsesActiveAsDenominator()
	{
		// 2 events 20s apart. Active = 20s, well below the 5-min window — denominator clamps to 20s.
		// 2 / 20s × 3600 = 360/hr.
		RollingWindow w = new RollingWindow(AFK_30S);
		w.recordEvent(COPPER, 0L);
		w.recordEvent(COPPER, 20_000L);
		double rate = w.activeRatePerHour(FIVE_MIN, 20_000L);
		assertEquals(360.0, rate, 0.5);
	}

	@Test
	public void trailingGapAdvancesActiveTimeUntilThreshold()
	{
		// One event at t=0, query at t=10s (well below 30s threshold). Active should be ~10s.
		RollingWindow w = new RollingWindow(AFK_30S);
		w.recordEvent(COPPER, 0L);
		assertEquals(10_000L, w.activeTimeMs(10_000L));
		// At t=60s (past threshold), active time freezes at threshold.
		assertEquals(AFK_30S, w.activeTimeMs(60_000L));
	}

	// --- v0.3.2 wall-clock auto-hide tests ---
	// hasEventsWithinWallTime is the auto-hide proxy. Distinct from activeRatePerHour
	// because the rate calc operates on the (AFK-frozen) active-time axis, while auto-hide
	// is a real-elapsed-time concern.

	@Test
	public void hasEventsWithinWallTime_emptyWindow_false()
	{
		RollingWindow w = new RollingWindow(AFK_30S);
		assertFalse(w.hasEventsWithinWallTime(FIVE_MIN, 0L));
		assertFalse(w.hasEventsWithinWallTime(FIVE_MIN, 1_000_000L));
	}

	@Test
	public void hasEventsWithinWallTime_recentEvent_true()
	{
		RollingWindow w = new RollingWindow(AFK_30S);
		w.recordEvent(COPPER, 100_000L);
		// 60s after the event, well within the 5-min window.
		assertTrue(w.hasEventsWithinWallTime(FIVE_MIN, 160_000L));
	}

	@Test
	public void hasEventsWithinWallTime_eventAtBoundary_true()
	{
		// Inclusive boundary: event exactly windowMs old should count.
		RollingWindow w = new RollingWindow(AFK_30S);
		w.recordEvent(COPPER, 0L);
		assertTrue(w.hasEventsWithinWallTime(FIVE_MIN, FIVE_MIN));
	}

	@Test
	public void hasEventsWithinWallTime_eventPastWindow_false()
	{
		// Event from 6 minutes ago, window is 5 minutes.
		RollingWindow w = new RollingWindow(AFK_30S);
		w.recordEvent(COPPER, 0L);
		assertFalse(w.hasEventsWithinWallTime(FIVE_MIN, FIVE_MIN + ONE_MIN));
	}

	@Test
	public void hasEventsWithinWallTime_drainsNaturally_unlikeRate()
	{
		// Regression guard for the v0.3.2 fix. Pre-fix, the overlay's auto-hide check used
		// `activeRatePerHour > 0`. After AFK, currentActive freezes at cumulativeActiveMs +
		// afkThresholdMs, and the rate-window cutoff freezes with it, so events from the
		// pre-AFK burst stay inside the window forever. Wall-clock semantics drain
		// correctly: as wall time advances past windowMs since the last event, the check
		// returns false even though the active-time-based rate would still be > 0.
		RollingWindow w = new RollingWindow(AFK_30S);
		// Mine a quick burst, then walk away.
		w.recordEvent(COPPER, 0L);
		w.recordEvent(COPPER, 5_000L);
		w.recordEvent(COPPER, 10_000L);

		// Immediately after, wall-clock check sees recent activity.
		assertTrue(w.hasEventsWithinWallTime(FIVE_MIN, 10_500L));
		// Active-time-based rate also > 0 here.
		assertTrue(w.activeRatePerHour(FIVE_MIN, 10_500L) > 0.0);

		// Wait 10 minutes (well past the 5-minute window).
		long after10Min = 10_000L + 10 * ONE_MIN;
		// Wall-clock check correctly drained.
		assertFalse("wall-clock check must return false after window passes",
			w.hasEventsWithinWallTime(FIVE_MIN, after10Min));
		// Rate, by contrast, is still > 0 because active-time froze at AFK_30S past the
		// last event and the cutoff froze with it. This is the bug v0.3.2 routes around.
		assertTrue("rate is still > 0 (active-time froze) — confirms why we needed a separate check",
			w.activeRatePerHour(FIVE_MIN, after10Min) > 0.0);
	}

	@Test
	public void hasEventsWithinWallTime_iteratesFromTail_isEfficient()
	{
		// 1000 events at 1ms intervals. Tail-first iteration should return on the first
		// element past the cutoff, not scan the whole deque. Asserts behavior, not perf —
		// but a future regression that switches to head-first iteration would still produce
		// correct results, just expensively. We assert correctness here; perf is implicit.
		RollingWindow w = new RollingWindow(AFK_30S);
		for (long i = 0; i < 1000; i++)
		{
			w.recordEvent(COPPER, i);
		}
		// Window of 100ms, query at t=2000 — only the tail-end events (900-999) qualify.
		// Wait, those are also outside 100ms of t=2000 (they're at t=999, so 1001ms old).
		// Let me re-frame: events 0-999 at ms intervals, query at t=999.
		// 100ms window from t=999 means events with wallTimeMs >= 899 qualify. That's events 899-999.
		assertTrue(w.hasEventsWithinWallTime(100L, 999L));
		// Window of 100ms at t=2000 means events with wallTimeMs >= 1900 qualify. None do.
		assertFalse(w.hasEventsWithinWallTime(100L, 2000L));
	}

	@Test
	public void hasEventsWithinWallTime_clearedWindow_false()
	{
		// After clear(), the wall-clock check must return false even if events were
		// previously recorded.
		RollingWindow w = new RollingWindow(AFK_30S);
		w.recordEvent(COPPER, 1000L);
		assertTrue(w.hasEventsWithinWallTime(FIVE_MIN, 1500L));
		w.clear();
		assertFalse(w.hasEventsWithinWallTime(FIVE_MIN, 1500L));
	}

	@Test
	public void hasEventsWithinWallTime_afterRestoreFromSnapshot_works()
	{
		// Persistence round-trip must preserve wall-clock check semantics. Existing events'
		// wallTimeMs survives the snapshot.
		RollingWindow original = new RollingWindow(AFK_30S);
		original.recordEvent(COPPER, 1000L);
		original.recordEvent(COPPER, 2000L);
		RollingWindow.Snapshot snap = original.exportSnapshot();

		RollingWindow restored = new RollingWindow(AFK_30S);
		restored.restoreFromSnapshot(snap);
		assertTrue(restored.hasEventsWithinWallTime(FIVE_MIN, 2500L));
		assertFalse(restored.hasEventsWithinWallTime(100L, 5000L)); // events too old for 100ms window
	}
}

package com.josiahcooper.miningstats;

import net.runelite.api.ItemID;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;

import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

/**
 * Light sanity coverage for the static lookup tables. The compile step itself is the primary
 * verification (constant names must resolve against the RuneLite API); these tests just
 * confirm the lookup wiring is correct.
 */
public class StaticDataTest
{
	@Test
	public void everyOreRoundTripsByItemId()
	{
		for (Ores o : Ores.values())
		{
			assertEquals(o, Ores.fromItemId(o.itemId()));
			assertTrue(Ores.isOre(o.itemId()));
			assertEquals(o.displayName(), Ores.displayName(o.itemId()));
		}
	}

	@Test
	public void unknownItemIdReturnsNullAndUnknownLabel()
	{
		assertNull(Ores.fromItemId(-999));
		assertFalse(Ores.isOre(-999));
		assertTrue(Ores.displayName(-999).startsWith("Unknown"));
	}

	/**
	 * v0.1.1 regression test. The v0.1.0 release shipped without Barronite shards in the enum,
	 * causing Camdozaal mining to register Mining XP but zero Ores/hr. Pinning by item ID 25676
	 * so a future refactor that drops the entry trips this test by name.
	 */
	@Test
	public void barroniteShardsAreRecognizedAsOre()
	{
		assertTrue("BARRONITE_SHARDS must be an ore (v0.1.1 fix)",
			Ores.isOre(ItemID.BARRONITE_SHARDS));
		assertEquals(Ores.BARRONITE_SHARDS, Ores.fromItemId(ItemID.BARRONITE_SHARDS));
		assertEquals("Barronite shards", Ores.displayName(ItemID.BARRONITE_SHARDS));
	}

	/**
	 * Gem-rock yields (Lunar Isle, Shilo Village) — added in v0.1.1. All seven gem variants
	 * mine-able from gem rocks must register as ores. Onyx is intentionally excluded
	 * (TzHaar/Trahaearn-only, not a Mining yield).
	 */
	@Test
	public void gemRockYieldsAreRecognized()
	{
		List<Integer> gemItemIds = Arrays.asList(
			ItemID.UNCUT_SAPPHIRE,
			ItemID.UNCUT_EMERALD,
			ItemID.UNCUT_RUBY,
			ItemID.UNCUT_DIAMOND,
			ItemID.UNCUT_OPAL,
			ItemID.UNCUT_JADE,
			ItemID.UNCUT_RED_TOPAZ
		);
		for (int id : gemItemIds)
		{
			assertTrue("Gem item " + id + " must be a recognized ore", Ores.isOre(id));
			assertNotNull(Ores.fromItemId(id));
		}
	}

	/**
	 * Catches copy-paste bugs where two enum entries point at the same item ID (the second
	 * would silently overwrite the first in BY_ID).
	 */
	@Test
	public void noDuplicateItemIdsAcrossEnum()
	{
		Set<Integer> seen = new HashSet<>();
		for (Ores o : Ores.values())
		{
			assertTrue("Duplicate itemId " + o.itemId() + " on " + o.name(),
				seen.add(o.itemId()));
		}
	}

	@Test
	public void miningAnimationsSetIsNonEmptyAndRejectsNonMembers()
	{
		assertFalse(MiningAnimations.all().isEmpty());
		// Idle animation (-1) is never a mining swing.
		assertFalse(MiningAnimations.isMiningAnimation(-1));
		// Arbitrary non-mining animation (woodcutting bronze axe ~= 879) shouldn't match.
		assertFalse(MiningAnimations.isMiningAnimation(879));
	}

	@Test
	public void miningAnimationMembershipIsConsistent()
	{
		for (Integer id : MiningAnimations.all())
		{
			assertTrue("Expected " + id + " to be reported as a mining animation",
				MiningAnimations.isMiningAnimation(id));
		}
	}

	/**
	 * v0.3.1 regression guard. v0.2.0 + v0.3.0 imported from
	 * {@code net.runelite.api.AnimationID} which only exposes floor-mining variants
	 * (e.g. adamant = 628). Wall-mounted rocks like Camdozaal barronite emit the
	 * {@code _WALL} variant (adamant wall = 6756), which the gameval namespace exposes
	 * but the legacy namespace did not. v0.3.1 migrates to gameval and includes the
	 * full variant lineup. Hardcoding the canonical Jagex animation IDs here so any
	 * future namespace shuffling that loses a variant fails the test loudly.
	 */
	@Test
	public void wallMountedRockAnimations_areRecognized()
	{
		// The load-bearing fix: adamant wall variant. Without this, Camdozaal barronite
		// mining never activates the gate. Same shape as the prod regression Josiah hit.
		assertTrue("HUMAN_MINING_ADAMANT_PICKAXE_WALL (6756) — v0.3.1 fix's anchor",
			MiningAnimations.isMiningAnimation(6756));

		// Sanity: the floor variants we already had still resolve. Stable IDs from
		// gameval AnimationID — these are Jagex internal cache IDs, fixed by the game data.
		assertTrue("HUMAN_MINING_ADAMANT_PICKAXE (628)",
			MiningAnimations.isMiningAnimation(628));
		assertTrue("HUMAN_MINING_RUNE_PICKAXE (624)",
			MiningAnimations.isMiningAnimation(624));
		assertTrue("HUMAN_MINING_DRAGON_PICKAXE (7139)",
			MiningAnimations.isMiningAnimation(7139));

		// Representative coverage of other wall variants — Trahaearn mine, Prifddinas
		// mine, anywhere with vertical rock walls would emit one of these per pickaxe.
		assertTrue("HUMAN_MINING_RUNE_PICKAXE_WALL (6752)",
			MiningAnimations.isMiningAnimation(6752));
		assertTrue("HUMAN_MINING_BRONZE_PICKAXE_WALL (6753)",
			MiningAnimations.isMiningAnimation(6753));
		assertTrue("HUMAN_MINING_IRON_PICKAXE_WALL (6754)",
			MiningAnimations.isMiningAnimation(6754));
		assertTrue("HUMAN_MINING_STEEL_PICKAXE_WALL (6755)",
			MiningAnimations.isMiningAnimation(6755));
		assertTrue("HUMAN_MINING_MITHRIL_PICKAXE_WALL",
			MiningAnimations.isMiningAnimation(AnimationID.HUMAN_MINING_MITHRIL_PICKAXE_WALL));

		// No-reach-forward variant — alternate orientation handled by Jagex for some
		// rock geometries. Same coverage gap as wall variants in pre-0.3.1.
		assertTrue("HUMAN_MINING_ADAMANT_PICKAXE_NOREACHFORWARD (6750)",
			MiningAnimations.isMiningAnimation(6750));

		// Power-swing variant — rare swing animation used in some special mining
		// activities. Included for completeness.
		assertTrue("PICKAXE_POWER_SWING_ADAMANT",
			MiningAnimations.isMiningAnimation(AnimationID.PICKAXE_POWER_SWING_ADAMANT));
	}

	/**
	 * Membership-count sanity check. v0.3.1 set should be substantially larger than
	 * v0.3.0's 13 entries — we now mirror the standard Mining plugin's coverage.
	 * If a future rebase accidentally drops half the entries, this test fails loudly
	 * before reaching a player.
	 */
	@Test
	public void miningAnimationsSetCoversAllPickaxeTiers()
	{
		// Lower bound — 13 was v0.3.0's value; we expect at least 60 with full variant
		// coverage across all pickaxe tiers (~17 tiers × ~4 variants each, minus a few
		// missing power-swing variants on cosmetic pickaxes).
		assertTrue("Expected substantially expanded animation set in v0.3.1+ (size: "
				+ MiningAnimations.all().size() + ")",
			MiningAnimations.all().size() >= 60);
	}
}

package com.josiahcooper.miningstats;

import net.runelite.api.InventoryID;
import net.runelite.api.ItemID;
import org.junit.Before;
import org.junit.Test;

import java.lang.reflect.Field;
import java.util.HashMap;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * Plugin-layer event-routing tests. Closes the test-coverage gap that let v0.3.0 ship with
 * a base-game regression invisible to the gate-level unit tests. {@link MiningSuccessGateTest}
 * exercises the gate in isolation; this class exercises the path from
 * {@link MiningStatsPlugin}'s {@code @Subscribe} handlers through container-id dispatch and
 * (v0.3.2) the per-tick animation heartbeat.
 *
 * <p>Dispatch tests use the package-private seams {@link MiningStatsPlugin#handleItemContainerEvent}
 * and {@link MiningStatsPlugin#handleAnimationHeartbeat} so the harness doesn't need to
 * construct RuneLite events or mock {@link net.runelite.api.ItemContainer} /
 * {@link net.runelite.api.Player}. Animation and XP-delta state are driven directly via the
 * gate API (the same calls the plugin's animation/XP handlers make).
 *
 * <p><strong>v0.3.2 status:</strong> the bank-handler architecture has been reverted after
 * the Endless Harvest test on a Leagues alt empirically demonstrated that bank events do not
 * fire while the bank UI is closed. The {@code bankEvent*} tests retained here verify the
 * post-revert contract — bank container events are ignored entirely, so a bank event
 * arriving between an XP delta and an inventory event must not perturb the inventory
 * pairing.
 */
public class PluginEventRoutingTest
{
	private static final int INVENTORY_ID = InventoryID.INVENTORY.getId();
	private static final int BANK_ID = InventoryID.BANK.getId();

	private MiningStatsPlugin plugin;
	private MiningSuccessGate gate;
	private RollingWindow window;

	@Before
	public void setUp() throws Exception
	{
		plugin = new MiningStatsPlugin();
		gate = new MiningSuccessGate();
		// 30s AFK threshold matches the plugin's default config; doesn't interact with the
		// gate logic under test, only with RollingWindow's active-ms tracking.
		window = new RollingWindow(30_000L);
		setField(plugin, "miningGate", gate);
		setField(plugin, "rollingWindow", window);
	}

	private static void setField(Object target, String name, Object value) throws Exception
	{
		Field f = target.getClass().getDeclaredField(name);
		f.setAccessible(true);
		f.set(target, value);
	}

	private static Map<Integer, Integer> snapshot(Object... pairs)
	{
		Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((Integer) pairs[i], (Integer) pairs[i + 1]);
		}
		return m;
	}

	// --- Scenario I distinguisher ---

	/**
	 * Clean base-game swing — animation, XP delta, inventory increment. No bank events.
	 * Mirrors the trace Josiah is reporting broken at Camdozaal calcified rocks. If this
	 * fails, the simple inventory path is broken at the plugin layer; v0.2.0 has the same
	 * regression; rollback target should be v0.1.1 not v0.2.0.
	 */
	@Test
	public void baseGameMiningSwing_noBankEvents_recordsEvent()
	{
		// Login: inventory baseline (mirrors the first ItemContainerChanged after login).
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(), 1000L);
		assertEquals("inventory baseline must not emit", 0, window.totalCount());

		// Swing: animation, then XP delta, then inventory gains an ore.
		gate.recordMiningAnimation(2000L);
		gate.onMiningXpDelta(2100L);
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(ItemID.COPPER_ORE, 1), 2150L);

		assertEquals("ore must record after anim+XP+inv coincidence",
			1, window.totalCount());
		assertEquals(1, window.totalCount(ItemID.COPPER_ORE));
	}

	/**
	 * Inventory-event-first ordering (XP delta arrives after the inventory event). Same
	 * coincidence requirement; gate buffers the inventory diff for the upcoming XP delta.
	 * Sanity check that both orderings work via the plugin's dispatch seam, not just the
	 * one tested above.
	 */
	@Test
	public void baseGameMiningSwing_inventoryBeforeXp_recordsEvent()
	{
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(), 1000L);

		gate.recordMiningAnimation(2000L);
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(ItemID.COPPER_ORE, 1), 2050L);
		// Diff is held; not yet emitted.
		assertEquals(0, window.totalCount());
		// XP delta arrives within window — pairs with held diff. The gate API returns the
		// emit list, but the plugin's onStatChanged shell would route it into the rolling
		// window; this test calls the gate directly so we assert via gate output.
		assertEquals("held diff must be returned when XP delta arrives in window",
			1, gate.onMiningXpDelta(2100L).size());
	}

	/**
	 * Five successive swings — exactly the steady-state Josiah is reporting broken. First
	 * swing baselines inventory; swings 2–5 each record one ore. Tests that the simple path
	 * is durable across multiple iterations, not just one.
	 */
	@Test
	public void baseGameSteadyState_fiveSwings_recordsFour()
	{
		// Login baseline.
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(), 0L);

		// Five swings, each granting one ore. Swing 1 baselines inventory at the
		// plugin-layer side too (the post-swing-1 snapshot becomes the comparison base
		// for swing 2 onwards).
		for (int swing = 1; swing <= 5; swing++)
		{
			long animT = swing * 5000L;        // ~5s between swings, well under 3s gate
			long xpT = animT + 100L;
			long invT = animT + 150L;
			gate.recordMiningAnimation(animT);
			gate.onMiningXpDelta(xpT);
			plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(ItemID.COPPER_ORE, swing), invT);
		}

		// Explicit baseline at t=0 (empty inventory) becomes the comparison point.
		// Each of the 5 swings produces a positive diff against the prior snapshot, so
		// all 5 should record under the correct contract.
		assertEquals("after explicit baseline + 5 swings, all 5 ores recorded",
			5, window.totalCount(ItemID.COPPER_ORE));
	}

	// --- Scenario II distinguisher ---

	/**
	 * Bank events arriving between an XP delta and an inventory event must not steal the
	 * pairing. Pre-v0.3.2 this was the hypothesized Scenario II bug at the gate level; in
	 * v0.3.2 the bank handler is fully reverted and bank container events are ignored at
	 * the plugin's dispatch layer, so the test now verifies a stronger property: bank events
	 * have no observable effect at all on the inventory path. Passes naturally.
	 */
	@Test
	public void bankEventBetweenXpAndInventory_doesNotStealInventoryEmit()
	{
		// Login baseline (inventory only — bank is no longer routed in v0.3.2).
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(), 1000L);

		// Swing: animation, then XP delta, then BANK event with diff, then inventory event.
		gate.recordMiningAnimation(2000L);
		gate.onMiningXpDelta(2100L);

		// Bank event with non-empty diff arrives between the XP delta and the inventory
		// event. Pre-v0.3.2 this could perturb the gate's pairing; v0.3.2 drops bank events
		// entirely at the dispatch layer, so the buffered XP delta survives intact.
		plugin.handleItemContainerEvent(BANK_ID, snapshot(ItemID.LOGS, 5), 2150L);

		// Inventory gains the actual mined ore — pairs with the still-buffered XP delta.
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(ItemID.COPPER_ORE, 1), 2200L);

		assertEquals("inventory ore must record even when a bank event interleaves",
			1, window.totalCount(ItemID.COPPER_ORE));
	}

	/**
	 * Bank events with empty diffs (e.g., container-state re-broadcast with no actual
	 * change) must not interfere with inventory event pairing. v0.3.2: the dispatch layer
	 * drops all bank container events before they reach the gate, so empty/full diffs are
	 * indistinguishable here — both are no-ops by virtue of routing.
	 */
	@Test
	public void emptyBankEvents_doNotInterfereWithBaseGameMining()
	{
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(), 1000L);
		plugin.handleItemContainerEvent(BANK_ID, snapshot(ItemID.LOGS, 100), 1000L);

		gate.recordMiningAnimation(2000L);
		gate.onMiningXpDelta(2100L);
		// Bank event with no change — diff is empty, should hit the early-out.
		plugin.handleItemContainerEvent(BANK_ID, snapshot(ItemID.LOGS, 100), 2150L);
		// Inventory event — should still pair with the buffered XP delta.
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(ItemID.COPPER_ORE, 1), 2200L);

		assertEquals(1, window.totalCount(ItemID.COPPER_ORE));
	}

	/**
	 * Equipment container events must not be routed anywhere. Catches any future regression
	 * where the dispatch logic accidentally widens to a third container.
	 */
	@Test
	public void equipmentContainerEvent_isIgnored()
	{
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(), 1000L);

		gate.recordMiningAnimation(2000L);
		gate.onMiningXpDelta(2100L);
		// Equipment container ID — should be ignored entirely.
		final int EQUIPMENT_ID = InventoryID.EQUIPMENT.getId();
		plugin.handleItemContainerEvent(EQUIPMENT_ID, snapshot(ItemID.RUNE_PICKAXE, 1), 2150L);
		// Inventory event with real ore — should record normally.
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(ItemID.COPPER_ORE, 1), 2200L);

		assertEquals(1, window.totalCount(ItemID.COPPER_ORE));
		assertEquals("equipment events must not record",
			0, window.totalCount(ItemID.RUNE_PICKAXE));
	}

	/**
	 * Null guard: events arriving before {@code startUp} populates the gate must be silently
	 * ignored. The {@code @Subscribe} shell's null guard handles this in production; this
	 * test verifies the helper preserves that guard.
	 */
	@Test
	public void containerEventBeforeGateInitialized_isIgnored() throws Exception
	{
		// Tear down the gate to simulate the pre-startUp race window.
		setField(plugin, "miningGate", null);

		// Should be a no-op; no NPE, no recording.
		plugin.handleItemContainerEvent(INVENTORY_ID, snapshot(ItemID.COPPER_ORE, 1), 2200L);
		assertEquals(0, window.totalCount());
	}

	// --- v0.3.2 animation heartbeat tests ---

	/**
	 * The per-tick heartbeat refreshes the gate when the player's current animation is a
	 * mining animation. Pre-v0.3.2, the gate only refreshed on {@code AnimationChanged}
	 * transitions, which left it stale during continuous in-place animation loops — title
	 * never green, ETA hidden during active mining. The heartbeat closes that gap.
	 */
	@Test
	public void heartbeatRefreshesGate_whenAnimationIsMiningAnim()
	{
		// Use adamant wall-rock animation (6756) — verified mining animation per StaticDataTest.
		final int ADAMANT_WALL_ANIM = 6756;
		assertFalse("gate must start unrefreshed", gate.isAnimationGateActive(1000L));

		plugin.handleAnimationHeartbeat(ADAMANT_WALL_ANIM, 1000L);
		assertTrue("gate must be active immediately after heartbeat",
			gate.isAnimationGateActive(1000L));
		assertTrue("gate must remain active just under animationGateMs",
			gate.isAnimationGateActive(3500L));
		assertFalse("gate must close past animationGateMs",
			gate.isAnimationGateActive(4500L));
	}

	/**
	 * The heartbeat is a no-op for non-mining animations. Catches a regression where the
	 * heartbeat would refresh the gate based on, e.g., a smithing or woodcutting animation
	 * that happens to share a numerical neighborhood with mining anims.
	 */
	@Test
	public void heartbeatDoesNotRefreshGate_forNonMiningAnimation()
	{
		// -1 is the OSRS idle/no-animation sentinel; not in MiningAnimations.
		final int IDLE = -1;
		plugin.handleAnimationHeartbeat(IDLE, 1000L);
		assertFalse("gate must remain inactive when animation is idle",
			gate.isAnimationGateActive(1000L));
	}

	/**
	 * Heartbeat must continue to refresh the gate during sustained mining. Reproduces the
	 * FlowersOEvil-reported bug pattern in unit form: many ticks, no inter-tick
	 * AnimationChanged events (only the heartbeat is firing), gate must stay open.
	 */
	@Test
	public void heartbeatKeepsGateOpenAcrossManyTicks_simulatesContinuousMining()
	{
		final int ADAMANT_WALL_ANIM = 6756;
		// Simulate 30 game ticks of continuous mining. Without the heartbeat the gate would
		// close 3000ms after the first tick; with it, every tick refreshes.
		for (int tick = 0; tick < 30; tick++)
		{
			long now = 1000L + tick * 600L; // 600ms per tick = standard OSRS tick rate
			plugin.handleAnimationHeartbeat(ADAMANT_WALL_ANIM, now);
			assertTrue("gate must stay open at tick " + tick,
				gate.isAnimationGateActive(now));
		}
	}

	/**
	 * Null guard: heartbeat ticks arriving before {@code startUp} populates the gate must
	 * be silently ignored.
	 */
	@Test
	public void heartbeatBeforeGateInitialized_isIgnored() throws Exception
	{
		setField(plugin, "miningGate", null);
		// Should be a no-op; no NPE.
		plugin.handleAnimationHeartbeat(6756, 1000L);
	}
}

package com.josiahcooper.miningstats;

import net.runelite.api.ItemID;
import org.junit.Test;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * v0.3.2 contract: pure positive-diff over arbitrary item IDs, with a curated blacklist of
 * categorically-non-mining items filtered out before return. Mining-discrimination by timing
 * (animation + XP coincidence) remains the {@link MiningSuccessGate}'s responsibility; the
 * blacklist here is a NEGATIVE filter — anything not on it still passes through, preserving
 * v0.2.0's "future Jagex yield won't silently zero-rate" property.
 */
public class InventoryDeltaTest
{
	private static final int BIRD_NEST = 5070;     // non-ore but NOT in the v0.3.2 blacklist; still reported

	private static final int COINS = 995;
	private static final int BRONZE_BAR = 2349;
	private static final int RUNE_BAR = 2363;
	private static final int UNCUT_DIAMOND = 1617;
	private static final int UNCUT_SAPPHIRE = 1623;
	private static final int CLUE_GEODE_EASY = 19887;
	private static final int CLUE_SCROLL_BEGINNER = 23182;
	private static final int SCROLL_BOX_BEGINNER = 26739;

	private static Map<Integer, Integer> map(Object... pairs)
	{
		Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((Integer) pairs[i], (Integer) pairs[i + 1]);
		}
		return m;
	}

	// --- Core positive-diff semantics ---

	@Test
	public void emptyToEmptyReportsNothing()
	{
		assertTrue(InventoryDelta.itemsGained(map(), map()).isEmpty());
	}

	@Test
	public void firstItemPickupReports()
	{
		List<Integer> gained = InventoryDelta.itemsGained(
			map(),
			map(ItemID.COPPER_ORE, 1));
		assertEquals(1, gained.size());
		assertEquals(Integer.valueOf(ItemID.COPPER_ORE), gained.get(0));
	}

	@Test
	public void stackGrowsByExactDelta()
	{
		List<Integer> gained = InventoryDelta.itemsGained(
			map(ItemID.COPPER_ORE, 5),
			map(ItemID.COPPER_ORE, 8));
		assertEquals(3, gained.size());
		for (Integer id : gained)
		{
			assertEquals(Integer.valueOf(ItemID.COPPER_ORE), id);
		}
	}

	@Test
	public void stackShrinksReportsNothing()
	{
		// Drop or bank — never count.
		List<Integer> gained = InventoryDelta.itemsGained(
			map(ItemID.COPPER_ORE, 5),
			map(ItemID.COPPER_ORE, 2));
		assertTrue(gained.isEmpty());
	}

	@Test
	public void mixedDeltaCountsOnlyTheGainer()
	{
		List<Integer> gained = InventoryDelta.itemsGained(
			map(ItemID.COPPER_ORE, 5),
			map(ItemID.COPPER_ORE, 5, ItemID.IRON_ORE, 2));
		assertEquals(2, gained.size());
		for (Integer id : gained)
		{
			assertEquals(Integer.valueOf(ItemID.IRON_ORE), id);
		}
	}

	@Test
	public void nonBlacklistedNonOreItemStillAppearsInDiff()
	{
		// v0.3.2 contract: the blacklist is narrow (categorical non-mining-yields). Other
		// non-ore items (bird's nest, future Jagex content) still pass through; the gate
		// decides whether to discard based on animation + XP coincidence.
		List<Integer> gained = InventoryDelta.itemsGained(
			map(ItemID.COPPER_ORE, 3),
			map(ItemID.COPPER_ORE, 4, BIRD_NEST, 1));
		assertEquals(2, gained.size());
		assertTrue(gained.contains(ItemID.COPPER_ORE));
		assertTrue(gained.contains(BIRD_NEST));
	}

	// --- v0.3.2 blacklist coverage ---
	// Each excluded category gets a fixture mirroring the empirical Leagues case: a plausible
	// mining-time inventory delta containing both blacklisted items and a real ore. Only the
	// real ore should increment the yield list.

	@Test
	public void coinsAreBlacklisted_leaguesEndlessHarvestCase()
	{
		// Reproduces the FlowersOEvil prod observation: coin-drop relic produces ~1000 coins
		// per swing alongside a single ore. Pre-v0.3.2 inflated Ores/hr to ~375k.
		List<Integer> gained = InventoryDelta.itemsGained(
			map(),
			map(COINS, 1000, ItemID.COAL, 1));
		assertEquals("only the coal should count, not the 1000 coins",
			1, gained.size());
		assertEquals(Integer.valueOf(ItemID.COAL), gained.get(0));
	}

	@Test
	public void barsAreBlacklisted_leaguesAutoSmeltCase()
	{
		// Smithing relic auto-converts ore to bar in inventory; bar is not the mining yield.
		List<Integer> gained = InventoryDelta.itemsGained(
			map(),
			map(BRONZE_BAR, 1, RUNE_BAR, 1, ItemID.MITHRIL_ORE, 1));
		assertEquals("only the mithril ore should count",
			1, gained.size());
		assertEquals(Integer.valueOf(ItemID.MITHRIL_ORE), gained.get(0));
	}

	@Test
	public void uncutGemsAreBlacklisted()
	{
		// Random gem drops while mining (~0.4%/rock); reward, not a mining yield.
		List<Integer> gained = InventoryDelta.itemsGained(
			map(),
			map(UNCUT_DIAMOND, 1, UNCUT_SAPPHIRE, 1, ItemID.IRON_ORE, 1));
		assertEquals(1, gained.size());
		assertEquals(Integer.valueOf(ItemID.IRON_ORE), gained.get(0));
	}

	@Test
	public void clueGeodesAreBlacklisted()
	{
		// Random clue geode drops while mining (~1%/rock).
		List<Integer> gained = InventoryDelta.itemsGained(
			map(),
			map(CLUE_GEODE_EASY, 1, ItemID.COPPER_ORE, 1));
		assertEquals(1, gained.size());
		assertEquals(Integer.valueOf(ItemID.COPPER_ORE), gained.get(0));
	}

	@Test
	public void clueScrollsAndScrollBoxAreBlacklisted()
	{
		// Beginner scroll box specifically targets the Leagues observation; broader clue
		// scroll IDs cover any future cross-content interaction.
		List<Integer> gained = InventoryDelta.itemsGained(
			map(),
			map(CLUE_SCROLL_BEGINNER, 1, SCROLL_BOX_BEGINNER, 1, ItemID.COPPER_ORE, 1));
		assertEquals(1, gained.size());
		assertEquals(Integer.valueOf(ItemID.COPPER_ORE), gained.get(0));
	}

	@Test
	public void purelyBlacklistedDeltaReportsNothing()
	{
		// The Leagues catastrophe-without-mining case: only coins + a bar arrive. No mining
		// yield → empty list → upstream gate sees diff.isEmpty() and skips the held-diff
		// machinery entirely. Critical: prevents blacklisted items from consuming the
		// buffered XP delta and starving subsequent real ore events.
		List<Integer> gained = InventoryDelta.itemsGained(
			map(),
			map(COINS, 500, BRONZE_BAR, 1));
		assertTrue("blacklisted-only diff must produce empty gain list",
			gained.isEmpty());
	}

	@Test
	public void blacklistContentsAreTheExpectedSet()
	{
		// Smoke test catching accidental removal — if a future edit drops a category, this
		// fails fast before behavior bugs ship to prod.
		java.util.Set<Integer> bl = InventoryDelta.yieldBlacklist();
		assertTrue("coins must be blacklisted", bl.contains(COINS));
		assertTrue("bronze bar must be blacklisted", bl.contains(BRONZE_BAR));
		assertTrue("rune bar must be blacklisted", bl.contains(RUNE_BAR));
		assertTrue("uncut diamond must be blacklisted", bl.contains(UNCUT_DIAMOND));
		assertTrue("clue geode (easy) must be blacklisted", bl.contains(CLUE_GEODE_EASY));
		assertTrue("scroll box (beginner) must be blacklisted", bl.contains(SCROLL_BOX_BEGINNER));
		// Negative: bird's nest (a non-ore but legitimate random drop in some contexts) is NOT
		// on the list — we don't want to over-filter and risk silently zero-rating real yields.
		assertFalse("bird's nest must NOT be blacklisted", bl.contains(BIRD_NEST));
		assertFalse("copper ore must NOT be blacklisted", bl.contains(ItemID.COPPER_ORE));
	}
}

