package com.josiahcooper.miningstats;

import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class InventoryEtaTest
{
	@Test
	public void zeroRateReturnsNoEstimate()
	{
		assertEquals(-1L, InventoryEta.etaSeconds(10, 0.0));
		assertEquals(-1L, InventoryEta.etaSeconds(10, -50.0));
	}

	@Test
	public void noFreeSlotsReturnsNoEstimate()
	{
		assertEquals(-1L, InventoryEta.etaSeconds(0, 600.0));
		assertEquals(-1L, InventoryEta.etaSeconds(-3, 600.0));
	}

	@Test
	public void typicalRateProducesExpectedEta()
	{
		// 10 free slots at 600 ores/hr = 6000ms/ore = 60s
		assertEquals(60L, InventoryEta.etaSeconds(10, 600.0));
		// 14 free slots at 300 ores/hr = 12000ms/ore = 168s
		assertEquals(168L, InventoryEta.etaSeconds(14, 300.0));
	}

	@Test
	public void formatNegativeReturnsEmDash()
	{
		assertEquals("—", InventoryEta.formatEta(-1));
		assertEquals("—", InventoryEta.formatEta(-9999));
	}

	@Test
	public void formatSubMinuteShowsSeconds()
	{
		assertEquals("0s", InventoryEta.formatEta(0));
		assertEquals("45s", InventoryEta.formatEta(45));
		assertEquals("59s", InventoryEta.formatEta(59));
	}

	@Test
	public void formatMinuteShowsMinutesAndSeconds()
	{
		assertEquals("1m 0s", InventoryEta.formatEta(60));
		assertEquals("2m 5s", InventoryEta.formatEta(125));
		assertEquals("59m 59s", InventoryEta.formatEta(3599));
	}

	@Test
	public void formatHourShowsHoursAndMinutes()
	{
		assertEquals("1h 0m", InventoryEta.formatEta(3600));
		assertEquals("1h 2m", InventoryEta.formatEta(3725));
		assertEquals("2h 30m", InventoryEta.formatEta(9000));
	}

	@Test
	public void inventoryCapacityConstantIsTwentyEight()
	{
		assertEquals(28, InventoryEta.INVENTORY_CAPACITY);
		assertTrue(InventoryEta.INVENTORY_CAPACITY > 0);
	}
}

package com.josiahcooper.miningstats;

import net.runelite.api.ItemID;
import org.junit.Test;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

/**
 * v0.2.0 Path B detection contract: animation + Mining-XP-delta coincidence with inventory
 * increment, no item-ID enum gate. Each test simulates the event sequence with explicit
 * timestamps; the gate accepts {@code now} as a parameter so {@code System.currentTimeMillis}
 * is not in the test's path.
 *
 * <p>v0.3.2: bank-watch tests (formerly {@code bankPositive*}, {@code multiTickAutoDeposit*},
 * {@code partialDeposit*}, etc.) were removed alongside the bank-handler revert. The
 * Endless Harvest test on Leagues empirically demonstrated that bank events do not fire
 * while the bank UI is closed, so the architecture's load-bearing assumption was false.
 * The inventory-only path retained here is the v0.2.0 contract that has been load-bearing
 * since the namespace migration.
 */
public class MiningSuccessGateTest
{
	private static final int BIRD_NEST = 5070;          // not in Ores, not in v0.3.2 blacklist
	private static final int UNKNOWN_FUTURE_YIELD = 99999; // would-be future Jagex yield

	private static Map<Integer, Integer> inv(Object... pairs)
	{
		Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < pairs.length; i += 2)
		{
			m.put((Integer) pairs[i], (Integer) pairs[i + 1]);
		}
		return m;
	}

	// --- Core coincidence tests (Test 1 through Test 6 from the design doc) ---

	@Test
	public void xpThenInventoryWithinWindowAndAnimation_records()
	{
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(), 1000).isEmpty()); // baseline
		assertTrue(g.onMiningXpDelta(1100).isEmpty());
		List<Integer> emit = g.onInventoryChange(inv(ItemID.COPPER_ORE, 1), 1500);
		assertEquals(1, emit.size());
		assertEquals(Integer.valueOf(ItemID.COPPER_ORE), emit.get(0));
	}

	@Test
	public void inventoryDeltaWithoutXpDelta_doesNotRecord()
	{
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(), 1000).isEmpty());
		// Inventory event with no recent XP delta — buffered, not emitted.
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 1), 1100).isEmpty());
		// After window passes, buffer ages out without ever firing.
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 1), 3000).isEmpty());
	}

	@Test
	public void xpDeltaWithoutInventory_doesNotRecord()
	{
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(), 1000).isEmpty());
		assertTrue(g.onMiningXpDelta(1100).isEmpty());
		assertTrue(g.onMiningXpDelta(1500).isEmpty());
		assertTrue(g.onMiningXpDelta(2000).isEmpty());
	}

	@Test
	public void nonEnumItemIdRecordsCorrectly_provesEnumDemotion()
	{
		// This is the headline win of Path B: items not in Ores still get counted, so the
		// next Jagex content drop doesn't silently zero-rate like Barronite shards did in v0.1.0.
		// (Note: 99999 is also not in v0.3.2's InventoryDelta blacklist, so it reaches the gate.)
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(), 1000).isEmpty());
		assertTrue(g.onMiningXpDelta(1100).isEmpty());
		List<Integer> emit = g.onInventoryChange(inv(UNKNOWN_FUTURE_YIELD, 1), 1500);
		assertEquals(1, emit.size());
		assertEquals(Integer.valueOf(UNKNOWN_FUTURE_YIELD), emit.get(0));
		assertFalse("test assumes ID isn't in Ores", Ores.isOre(UNKNOWN_FUTURE_YIELD));
	}

	@Test
	public void xpAndInventoryWithoutAnimation_doesNotRecord()
	{
		// Animation gate is the Wintertodt-FP killer: brazier repair grants Mining XP via
		// hammer animation (not in MiningAnimations), so even if a coincident inventory event
		// happened, the gate must reject it.
		MiningSuccessGate g = new MiningSuccessGate();
		// Note: no recordMiningAnimation call.
		assertTrue(g.onInventoryChange(inv(), 1000).isEmpty());
		assertTrue(g.onMiningXpDelta(1100).isEmpty());
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 1), 1500).isEmpty());
	}

	@Test
	public void inventoryThenXpWithinWindowAndAnimation_records()
	{
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(), 1000).isEmpty()); // baseline
		// Inventory comes first; held.
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 1), 1100).isEmpty());
		// XP delta inside window pairs with held diff.
		List<Integer> emit = g.onMiningXpDelta(1200);
		assertEquals(1, emit.size());
		assertEquals(Integer.valueOf(ItemID.COPPER_ORE), emit.get(0));
	}

	// --- Edge cases protecting non-obvious behavior ---

	@Test
	public void heldDiffAgesOut_xpDeltaBeyondWindowDoesNotEmit()
	{
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(), 1000).isEmpty());
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 1), 1100).isEmpty()); // held
		// XP delta arrives 1500ms later — outside 1200ms window.
		assertTrue(g.onMiningXpDelta(2700).isEmpty());
	}

	@Test
	public void xpDeltaConsumed_doesNotDoubleFireOnSecondInventoryEvent()
	{
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(), 1000).isEmpty());
		assertTrue(g.onMiningXpDelta(1100).isEmpty());
		// First inventory event consumes the buffered XP delta.
		List<Integer> emit1 = g.onInventoryChange(inv(ItemID.COPPER_ORE, 1), 1200);
		assertEquals(1, emit1.size());
		// Second inventory event with no fresh XP delta should NOT fire.
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 1, BIRD_NEST, 1), 1300).isEmpty());
	}

	@Test
	public void multiUnitGain_yieldsOneEntryPerUnit()
	{
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 5), 1000).isEmpty()); // baseline
		assertTrue(g.onMiningXpDelta(1100).isEmpty());
		List<Integer> emit = g.onInventoryChange(inv(ItemID.COPPER_ORE, 8), 1200);
		assertEquals(3, emit.size());
		for (Integer id : emit)
		{
			assertEquals(Integer.valueOf(ItemID.COPPER_ORE), id);
		}
	}

	@Test
	public void backToBackInventoryEventsBeforeXp_mergeIntoSingleEmit()
	{
		// Tick-jitter scenario: two swings' inventory events arrive before either's XP delta.
		// Merge behavior prevents the earlier swing's record from being silently dropped.
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(), 1000).isEmpty()); // baseline
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 1), 1100).isEmpty()); // hold COPPER
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 1, ItemID.IRON_ORE, 1), 1300).isEmpty()); // append IRON
		List<Integer> emit = g.onMiningXpDelta(1400);
		assertEquals(2, emit.size());
		assertTrue(emit.contains(ItemID.COPPER_ORE));
		assertTrue(emit.contains(ItemID.IRON_ORE));
	}

	@Test
	public void resetInventoryBaseline_clearsHeldDiff()
	{
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(), 1000).isEmpty());
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 1), 1100).isEmpty()); // hold
		g.resetInventoryBaseline();
		// After reset, the held diff is gone — XP delta should not retroactively emit.
		assertTrue(g.onMiningXpDelta(1200).isEmpty());
	}

	@Test
	public void animationGateActiveCheck_reflectsRecency()
	{
		MiningSuccessGate g = new MiningSuccessGate(3000L, 1200L);
		assertFalse(g.isAnimationGateActive(1000));
		g.recordMiningAnimation(1000);
		assertTrue(g.isAnimationGateActive(1000));
		assertTrue(g.isAnimationGateActive(3500));   // 2500ms < 3000ms gate
		assertFalse(g.isAnimationGateActive(4500));  // 3500ms > 3000ms gate
	}

	@Test
	public void droppedItemsIgnored_evenWithRecentXpAndAnimation()
	{
		// Stack shrinks (player drops ore mid-session) → not a positive diff → no record.
		MiningSuccessGate g = new MiningSuccessGate();
		g.recordMiningAnimation(1000);
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 5), 1000).isEmpty());
		assertTrue(g.onMiningXpDelta(1100).isEmpty());
		assertTrue(g.onInventoryChange(inv(ItemID.COPPER_ORE, 2), 1200).isEmpty());
	}
}

package com.josiahcooper.miningstats;

/**
 * Pure helper for computing and formatting time-to-full-inventory while mining.
 *
 * <p>Standalone (no RuneLite dependencies) so it can be unit-tested without mocking the client.
 */
public final class InventoryEta
{
	/** Standard OSRS inventory capacity. */
	public static final int INVENTORY_CAPACITY = 28;

	private InventoryEta()
	{
	}

	/**
	 * Estimated seconds until the inventory fills, given the current free-slot count and ore rate.
	 * Returns -1 when no estimate is meaningful (zero or negative rate / no free slots).
	 *
	 * <p>Ores in OSRS are unstackable, so each ore occupies one slot — free-slots is the count
	 * of ores remaining before the player must bank.
	 */
	public static long etaSeconds(int freeSlots, double oresPerHour)
	{
		if (oresPerHour <= 0 || freeSlots <= 0)
		{
			return -1L;
		}
		double oresPerSecond = oresPerHour / 3600.0;
		return Math.max(0L, Math.round(freeSlots / oresPerSecond));
	}

	/**
	 * Format a duration in seconds to a compact human-readable string. Returns {@code "—"} when
	 * the input is negative (no estimate).
	 */
	public static String formatEta(long seconds)
	{
		if (seconds < 0)
		{
			return "—"; // em-dash
		}
		if (seconds < 60)
		{
			return seconds + "s";
		}
		long minutes = seconds / 60;
		long secs = seconds % 60;
		if (minutes < 60)
		{
			return minutes + "m " + secs + "s";
		}
		long hours = minutes / 60;
		long mins = minutes % 60;
		return hours + "h " + mins + "m";
	}
}

package com.josiahcooper.miningstats;

import net.runelite.api.ItemID;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

/**
 * Mineable yields and their display names.
 *
 * <p>Coverage extended in v0.1.1 from the v0.1.0 conservative-standard list to include the
 * non-standard yields players hit during normal play: Camdozaal (Barronite shards), Granite
 * Quarry (3 weights), Sandstone Quarry (4 weights), Daeyalt Essence Mine, Fossil Island volcanic
 * ash, Motherlode pay-dirt, Lovakengj lovakite, Weiss basalt, and gem-rock yields (uncut
 * sapphire/emerald/ruby/diamond/opal/jade/red topaz).
 *
 * <p>Intentionally excluded: uncut onyx (TzHaar/Trahaearn-only, not a gem-rock yield), salt
 * rocks (urt/efh/te/ica/basalt salt — fringe content, low player overlap), tephra/calcite from
 * Volcanic Mine (group instance, separate scoring loop), Wintertodt bruma roots/kindling
 * (grants Mining XP via Firemaking activity, not a Mining yield), legacy DAEYALT_ORE 9632
 * (replaced by DAEYALT_ESSENCE post-Sins-of-the-Father), BARRONITE_DEPOSIT 25684 (rare
 * piece-container, opening it would double-count against shards which are the primary rate
 * signal).
 *
 * <p>If a future yield is missed: the player will see Mining XP increment but no Ores/hr or
 * Total tick. That's the v0.1.0 → v0.1.1 failure mode that triggered this expansion. A
 * coincidence-detection alternative (XP delta + same-tick inventory increment) is in the
 * v0.2.0 design notes in HANDOFF.md.
 */
public enum Ores
{
	// Standard pickaxe-mineable ores (v0.1.0)
	COPPER     (ItemID.COPPER_ORE,     "Copper"),
	TIN        (ItemID.TIN_ORE,        "Tin"),
	IRON       (ItemID.IRON_ORE,       "Iron"),
	COAL       (ItemID.COAL,           "Coal"),
	SILVER     (ItemID.SILVER_ORE,     "Silver"),
	GOLD       (ItemID.GOLD_ORE,       "Gold"),
	MITHRIL    (ItemID.MITHRIL_ORE,    "Mithril"),
	ADAMANTITE (ItemID.ADAMANTITE_ORE, "Adamantite"),
	RUNITE     (ItemID.RUNITE_ORE,     "Runite"),
	AMETHYST   (ItemID.AMETHYST,       "Amethyst"),
	BLURITE    (ItemID.BLURITE_ORE,    "Blurite"),
	CLAY       (ItemID.CLAY,           "Clay"),
	RUNE_ESSENCE (ItemID.RUNE_ESSENCE, "Rune essence"),
	PURE_ESSENCE (ItemID.PURE_ESSENCE, "Pure essence"),

	// Camdozaal (v0.1.1)
	BARRONITE_SHARDS (ItemID.BARRONITE_SHARDS, "Barronite shards"),

	// Granite quarry — yield depends on Mining level (v0.1.1)
	GRANITE_500G (ItemID.GRANITE_500G, "Granite (500g)"),
	GRANITE_2KG  (ItemID.GRANITE_2KG,  "Granite (2kg)"),
	GRANITE_5KG  (ItemID.GRANITE_5KG,  "Granite (5kg)"),

	// Sandstone quarry — yield depends on Mining level (v0.1.1)
	SANDSTONE_1KG  (ItemID.SANDSTONE_1KG,  "Sandstone (1kg)"),
	SANDSTONE_2KG  (ItemID.SANDSTONE_2KG,  "Sandstone (2kg)"),
	SANDSTONE_5KG  (ItemID.SANDSTONE_5KG,  "Sandstone (5kg)"),
	SANDSTONE_10KG (ItemID.SANDSTONE_10KG, "Sandstone (10kg)"),

	// Other non-standard mining yields (v0.1.1)
	DAEYALT_ESSENCE (ItemID.DAEYALT_ESSENCE, "Daeyalt essence"),
	VOLCANIC_ASH    (ItemID.VOLCANIC_ASH,    "Volcanic ash"),
	PAYDIRT         (ItemID.PAYDIRT,         "Pay-dirt"),
	LOVAKITE        (ItemID.LOVAKITE_ORE,    "Lovakite"),
	BASALT          (ItemID.BASALT,          "Basalt"),

	// Gem rocks — Lunar Isle, Shilo Village (v0.1.1)
	UNCUT_SAPPHIRE  (ItemID.UNCUT_SAPPHIRE,  "Uncut sapphire"),
	UNCUT_EMERALD   (ItemID.UNCUT_EMERALD,   "Uncut emerald"),
	UNCUT_RUBY      (ItemID.UNCUT_RUBY,      "Uncut ruby"),
	UNCUT_DIAMOND   (ItemID.UNCUT_DIAMOND,   "Uncut diamond"),
	UNCUT_OPAL      (ItemID.UNCUT_OPAL,      "Uncut opal"),
	UNCUT_JADE      (ItemID.UNCUT_JADE,      "Uncut jade"),
	UNCUT_RED_TOPAZ (ItemID.UNCUT_RED_TOPAZ, "Uncut red topaz");

	private static final Map<Integer, Ores> BY_ID;

	static
	{
		Map<Integer, Ores> m = new HashMap<>();
		for (Ores o : values())
		{
			m.put(o.itemId, o);
		}
		BY_ID = Collections.unmodifiableMap(m);
	}

	private final int itemId;
	private final String displayName;

	Ores(int itemId, String displayName)
	{
		this.itemId = itemId;
		this.displayName = displayName;
	}

	public int itemId()
	{
		return itemId;
	}

	public String displayName()
	{
		return displayName;
	}

	public static Ores fromItemId(int itemId)
	{
		return BY_ID.get(itemId);
	}

	public static boolean isOre(int itemId)
	{
		return BY_ID.containsKey(itemId);
	}

	public static String displayName(int itemId)
	{
		Ores o = BY_ID.get(itemId);
		return o == null ? "Unknown (" + itemId + ")" : o.displayName;
	}
}

package com.josiahcooper.miningstats;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.HashMap;
import java.util.Iterator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Time-windowed event store with AFK-aware accounting.
 *
 * <p>Each recorded event carries a wall-clock timestamp and a cumulative <em>active-time</em>
 * offset. Active time is wall-clock time with AFK gaps excised: if the gap between two
 * consecutive events meets or exceeds {@code afkThresholdMs}, that gap contributes zero
 * active time. Rate queries operate on the active-time axis, so a player who mines, AFKs,
 * and resumes sees a rate based on actual mining time rather than total elapsed time.
 *
 * <p>Two parallel state surfaces are maintained:
 * <ul>
 *   <li>A bounded events deque used for windowed rate calculations (subject to pruning).</li>
 *   <li>Lifetime per-ore counters that never decrement, feeding "session total" displays.</li>
 * </ul>
 *
 * <p>Framework-free by design: the caller supplies timestamps, so the class is fully
 * testable outside the RuneLite runtime.
 */
public final class RollingWindow
{
	/** Hard cap on retained active time. Sixty minutes covers the SPEC's 30-minute window twice over. */
	private static final long MAX_RETENTION_ACTIVE_MS = 60L * 60_000L;

	private long afkThresholdMs;
	private final Deque<Event> events = new ArrayDeque<>();

	private long cumulativeActiveMs = 0L;
	private long lastEventWallMs = Long.MIN_VALUE;

	private int sessionTotal = 0;
	private final Map<Integer, Integer> sessionByOre = new HashMap<>();

	public RollingWindow(long afkThresholdMs)
	{
		setAfkThresholdMs(afkThresholdMs);
	}

	/**
	 * Update the AFK threshold. Affects only future {@link #recordEvent} calls — events already
	 * recorded keep the active-time classification they were given under the previous threshold.
	 */
	public void setAfkThresholdMs(long afkThresholdMs)
	{
		if (afkThresholdMs <= 0)
		{
			throw new IllegalArgumentException("afkThresholdMs must be positive");
		}
		this.afkThresholdMs = afkThresholdMs;
	}

	public long afkThresholdMs()
	{
		return afkThresholdMs;
	}

	/** Record a successful mining event. Out-of-order timestamps (gap &lt;= 0) are ignored for active-time accounting but the event is still stored. */
	public void recordEvent(int oreId, long wallTimeMs)
	{
		if (lastEventWallMs != Long.MIN_VALUE)
		{
			long gap = wallTimeMs - lastEventWallMs;
			if (gap > 0 && gap < afkThresholdMs)
			{
				cumulativeActiveMs += gap;
			}
			// gap >= afkThresholdMs: AFK gap, contributes zero active time.
		}
		events.addLast(new Event(oreId, wallTimeMs, cumulativeActiveMs));
		lastEventWallMs = wallTimeMs;
		sessionTotal++;
		sessionByOre.merge(oreId, 1, Integer::sum);
		prune();
	}

	/**
	 * Active rate over the most recent {@code windowMs} of active time, expressed as events per hour.
	 * If accrued active time is shorter than the window, accrued active time is used as the denominator.
	 * Returns 0.0 when no active time has accrued.
	 */
	public double activeRatePerHour(long windowMs, long nowWallMs)
	{
		return activeRatePerHourFiltered(windowMs, nowWallMs, /* oreFilter */ -1);
	}

	/** Per-ore variant. */
	public double activeRatePerHour(int oreId, long windowMs, long nowWallMs)
	{
		return activeRatePerHourFiltered(windowMs, nowWallMs, oreId);
	}

	private double activeRatePerHourFiltered(long windowMs, long nowWallMs, int oreFilter)
	{
		long currentActive = currentActiveTime(nowWallMs);
		if (currentActive <= 0)
		{
			return 0.0;
		}
		long denomMs = Math.min(windowMs, currentActive);
		long cutoff = currentActive - windowMs;
		long count = 0;
		for (Event e : events)
		{
			if (e.activeTimeMs >= cutoff && (oreFilter == -1 || e.oreId == oreFilter))
			{
				count++;
			}
		}
		return count * 3_600_000.0 / denomMs;
	}

	/** Lifetime session count across all ores. */
	public int totalCount()
	{
		return sessionTotal;
	}

	/** Lifetime session count for a given ore. */
	public int totalCount(int oreId)
	{
		return sessionByOre.getOrDefault(oreId, 0);
	}

	/**
	 * True if at least one recorded event has a wall-clock timestamp within {@code windowMs}
	 * of {@code nowWallMs}. Used by the overlay's auto-hide check.
	 *
	 * <p>This is intentionally distinct from {@link #activeRatePerHour}: the rate calculation
	 * runs on the active-time axis, which freezes when the player goes AFK. Auto-hide is a
	 * wall-clock concern — the overlay should disappear after the player has been away from
	 * mining for {@code windowMs} of real elapsed time, regardless of whether the active-time
	 * cutoff has slid past stored events. Pre-v0.3.2 used {@code rate > 0} as the activity
	 * proxy, which incorrectly stayed true forever after AFK because both {@code currentActive}
	 * and the cutoff froze together, leaving stored events permanently inside the window.
	 *
	 * @param windowMs    look-back window in wall-clock milliseconds (typically the configured rolling window)
	 * @param nowWallMs   current wall-clock time
	 */
	public boolean hasEventsWithinWallTime(long windowMs, long nowWallMs)
	{
		long cutoff = nowWallMs - windowMs;
		// Iterate in reverse — most recent events are at the tail and most likely to satisfy.
		Iterator<Event> it = events.descendingIterator();
		while (it.hasNext())
		{
			Event e = it.next();
			if (e.wallTimeMs >= cutoff)
			{
				return true;
			}
			// Events are insertion-ordered ascending by wallTimeMs; once we see one older than
			// the cutoff while iterating tail-to-head, all earlier events are also older.
			return false;
		}
		return false;
	}

	/** Lifetime per-ore counts, ordered descending by count. */
	public Map<Integer, Integer> totalByOre()
	{
		Map<Integer, Integer> sorted = new LinkedHashMap<>();
		sessionByOre.entrySet().stream()
			.sorted((a, b) -> Integer.compare(b.getValue(), a.getValue()))
			.forEach(e -> sorted.put(e.getKey(), e.getValue()));
		return sorted;
	}

	/** Current cumulative active time in ms, including the trailing gap (capped at the AFK threshold). */
	public long activeTimeMs(long nowWallMs)
	{
		return currentActiveTime(nowWallMs);
	}

	/** Reset all state. */
	public void clear()
	{
		events.clear();
		sessionByOre.clear();
		sessionTotal = 0;
		cumulativeActiveMs = 0L;
		lastEventWallMs = Long.MIN_VALUE;
	}

	/**
	 * Export a serializable snapshot of all internal state. Used by {@link SessionPersistence}
	 * to survive client disconnects. The returned object is a defensive copy — mutating the
	 * snapshot's collections does not affect this window.
	 */
	public Snapshot exportSnapshot()
	{
		List<EventData> exported = new ArrayList<>(events.size());
		for (Event e : events)
		{
			exported.add(new EventData(e.oreId, e.wallTimeMs, e.activeTimeMs));
		}
		return new Snapshot(
			cumulativeActiveMs,
			lastEventWallMs,
			sessionTotal,
			Collections.unmodifiableList(exported),
			Collections.unmodifiableMap(new HashMap<>(sessionByOre))
		);
	}

	/**
	 * Restore state from a snapshot. Clears any existing state first. The AFK threshold is
	 * NOT touched — current threshold remains in effect for future events. Past events keep
	 * the active-time classification they were given when originally recorded, matching the
	 * documented {@link #setAfkThresholdMs} semantics.
	 */
	public void restoreFromSnapshot(Snapshot snap)
	{
		events.clear();
		sessionByOre.clear();
		for (EventData d : snap.events)
		{
			events.addLast(new Event(d.oreId, d.wallTimeMs, d.activeTimeMs));
		}
		sessionByOre.putAll(snap.sessionByOre);
		sessionTotal = snap.sessionTotal;
		cumulativeActiveMs = snap.cumulativeActiveMs;
		lastEventWallMs = snap.lastEventWallMs;
	}

	private long currentActiveTime(long nowWallMs)
	{
		if (lastEventWallMs == Long.MIN_VALUE)
		{
			return 0L;
		}
		long trailingGap = nowWallMs - lastEventWallMs;
		if (trailingGap < 0)
		{
			trailingGap = 0;
		}
		// Active time keeps ticking up to the AFK threshold past the last event, then freezes.
		long cappedGap = Math.min(trailingGap, afkThresholdMs);
		return cumulativeActiveMs + cappedGap;
	}

	private void prune()
	{
		long cutoff = cumulativeActiveMs - MAX_RETENTION_ACTIVE_MS;
		Iterator<Event> it = events.iterator();
		while (it.hasNext())
		{
			Event e = it.next();
			if (e.activeTimeMs < cutoff)
			{
				it.remove();
			}
			else
			{
				break; // events are insertion-ordered by activeTimeMs
			}
		}
	}

	private static final class Event
	{
		final int oreId;
		final long wallTimeMs;
		final long activeTimeMs;

		Event(int oreId, long wallTimeMs, long activeTimeMs)
		{
			this.oreId = oreId;
			this.wallTimeMs = wallTimeMs;
			this.activeTimeMs = activeTimeMs;
		}
	}

	/** Serializable triple mirroring the private {@code Event} class. */
	public static final class EventData
	{
		public final int oreId;
		public final long wallTimeMs;
		public final long activeTimeMs;

		public EventData(int oreId, long wallTimeMs, long activeTimeMs)
		{
			this.oreId = oreId;
			this.wallTimeMs = wallTimeMs;
			this.activeTimeMs = activeTimeMs;
		}
	}

	/** Immutable snapshot of {@link RollingWindow} internal state for persistence. */
	public static final class Snapshot
	{
		public final long cumulativeActiveMs;
		public final long lastEventWallMs;
		public final int sessionTotal;
		public final List<EventData> events;
		public final Map<Integer, Integer> sessionByOre;

		public Snapshot(long cumulativeActiveMs, long lastEventWallMs, int sessionTotal,
			List<EventData> events, Map<Integer, Integer> sessionByOre)
		{
			this.cumulativeActiveMs = cumulativeActiveMs;
			this.lastEventWallMs = lastEventWallMs;
			this.sessionTotal = sessionTotal;
			this.events = events;
			this.sessionByOre = sessionByOre;
		}
	}
}

package com.josiahcooper.miningstats;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * Serializes and parses {@link RollingWindow.Snapshot} for cross-session persistence.
 *
 * <p>The snapshot is intended to survive an OSRS client disconnect/reconnect during a long
 * mining session. Format is a single line, semicolon-separated records, comma-separated
 * fields — chosen to round-trip cleanly through any properties-style backing store and to
 * stay debuggable when dumped from {@code settings.properties}.
 *
 * <p>Format (v1):
 * <pre>
 * v=1;snap=&lt;wallMs&gt;;cum=&lt;cumulativeActiveMs&gt;;last=&lt;lastEventWallMs&gt;;tot=&lt;sessionTotal&gt;
 *   ;e=&lt;oreId&gt;,&lt;wallMs&gt;,&lt;activeMs&gt;        (repeated 0..n)
 *   ;o=&lt;oreId&gt;,&lt;count&gt;                       (repeated 0..n)
 * </pre>
 *
 * <p>The class is RuneLite-decoupled and pure-functional — all I/O is the responsibility of
 * the calling plugin layer.
 */
public final class SessionPersistence
{
	/**
	 * Discard snapshots older than this — matches {@link RollingWindow}'s 60-minute hard
	 * retention cap, so we never restore data that would be pruned anyway.
	 */
	public static final long DEFAULT_MAX_AGE_MS = 60L * 60_000L;

	/** Format version. Bumped if the on-wire layout changes incompatibly. */
	public static final int FORMAT_VERSION = 1;

	private SessionPersistence()
	{
	}

	/**
	 * Serialize the current snapshot. Returns {@code null} for an empty session
	 * ({@code sessionTotal == 0}) — empty snapshots are not worth persisting.
	 *
	 * @param snap            current snapshot (typically {@link RollingWindow#exportSnapshot()})
	 * @param snapshotWallMs  wall-clock time at which the snapshot was taken
	 */
	public static String serialize(RollingWindow.Snapshot snap, long snapshotWallMs)
	{
		if (snap == null || snap.sessionTotal == 0)
		{
			return null;
		}
		StringBuilder sb = new StringBuilder(256);
		sb.append("v=").append(FORMAT_VERSION);
		sb.append(";snap=").append(snapshotWallMs);
		sb.append(";cum=").append(snap.cumulativeActiveMs);
		sb.append(";last=").append(snap.lastEventWallMs);
		sb.append(";tot=").append(snap.sessionTotal);
		for (RollingWindow.EventData e : snap.events)
		{
			sb.append(";e=").append(e.oreId)
				.append(',').append(e.wallTimeMs)
				.append(',').append(e.activeTimeMs);
		}
		for (Map.Entry<Integer, Integer> tally : snap.sessionByOre.entrySet())
		{
			sb.append(";o=").append(tally.getKey()).append(',').append(tally.getValue());
		}
		return sb.toString();
	}

	/**
	 * Parse a serialized snapshot. Returns {@link Optional#empty()} if:
	 * <ul>
	 *   <li>{@code text} is null or blank;</li>
	 *   <li>format version doesn't match {@link #FORMAT_VERSION};</li>
	 *   <li>any required header field is missing or unparseable;</li>
	 *   <li>any event/ore record is malformed;</li>
	 *   <li>the snapshot is older than {@code maxAgeMs}.</li>
	 * </ul>
	 *
	 * <p>Malformed input never throws — it returns empty so the plugin can degrade to a fresh
	 * session without surfacing the error to the user.
	 */
	public static Optional<RollingWindow.Snapshot> parse(String text, long nowWallMs, long maxAgeMs)
	{
		if (text == null || text.isEmpty())
		{
			return Optional.empty();
		}
		try
		{
			String[] records = text.split(";");
			Long snapshotWallMs = null;
			Long cumulativeActiveMs = null;
			Long lastEventWallMs = null;
			Integer sessionTotal = null;
			boolean versionSeen = false;
			List<RollingWindow.EventData> events = new ArrayList<>();
			Map<Integer, Integer> sessionByOre = new HashMap<>();

			for (String record : records)
			{
				if (record.isEmpty())
				{
					continue;
				}
				int eq = record.indexOf('=');
				if (eq <= 0)
				{
					return Optional.empty();
				}
				String key = record.substring(0, eq);
				String val = record.substring(eq + 1);

				switch (key)
				{
					case "v":
						if (Integer.parseInt(val) != FORMAT_VERSION)
						{
							return Optional.empty();
						}
						versionSeen = true;
						break;
					case "snap":
						snapshotWallMs = Long.parseLong(val);
						break;
					case "cum":
						cumulativeActiveMs = Long.parseLong(val);
						break;
					case "last":
						lastEventWallMs = Long.parseLong(val);
						break;
					case "tot":
						sessionTotal = Integer.parseInt(val);
						break;
					case "e":
					{
						String[] parts = val.split(",");
						if (parts.length != 3)
						{
							return Optional.empty();
						}
						events.add(new RollingWindow.EventData(
							Integer.parseInt(parts[0]),
							Long.parseLong(parts[1]),
							Long.parseLong(parts[2])
						));
						break;
					}
					case "o":
					{
						String[] parts = val.split(",");
						if (parts.length != 2)
						{
							return Optional.empty();
						}
						sessionByOre.put(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]));
						break;
					}
					default:
						// Forward-compatibility: unknown keys are skipped, not rejected.
						break;
				}
			}

			if (!versionSeen || snapshotWallMs == null || cumulativeActiveMs == null
				|| lastEventWallMs == null || sessionTotal == null)
			{
				return Optional.empty();
			}
			if (nowWallMs - snapshotWallMs > maxAgeMs)
			{
				return Optional.empty();
			}

			return Optional.of(new RollingWindow.Snapshot(
				cumulativeActiveMs,
				lastEventWallMs,
				sessionTotal,
				events,
				sessionByOre
			));
		}
		catch (NumberFormatException | IndexOutOfBoundsException ex)
		{
			return Optional.empty();
		}
	}
}

package com.josiahcooper.miningstats;

import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

@Slf4j
@PluginDescriptor(
	name = "Mining Stats",
	description = "Honest per-hour mining rate via rolling window with AFK awareness and per-ore breakdown.",
	tags = {"mining", "skilling", "overlay", "stats"}
)
public class MiningStatsPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private MiningStatsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private MiningStatsOverlay overlay;

	@Inject
	private ItemManager itemManager;

	@Inject
	private ConfigManager configManager;

	@Getter
	private RollingWindow rollingWindow;

	/**
	 * Persistence key prefix under config group {@code miningstats}. Full key is
	 * {@code persisted.<normalizedPlayerName>}. Set dynamically via
	 * {@link ConfigManager#setConfiguration}, so it does NOT appear in the {@code @ConfigItem}
	 * settings panel.
	 */
	static final String PERSIST_KEY_PREFIX = "persisted.";

	/** Last seen logged-in player name, lowercased + whitespace-normalized. Null until first login. */
	private String lastKnownPlayerKey;

	/** Once-per-session flag preventing repeated load attempts after CONNECTION_LOST → LOGGED_IN cycles. */
	private boolean loadAttempted;

	/**
	 * Path B (v0.2.0): replaces the v0.1.x enum-membership gate with animation +
	 * XP-delta-coincidence discrimination. Owns inventory snapshot, animation timestamp,
	 * and the held-diff buffer.
	 */
	private MiningSuccessGate miningGate;

	private int baselineMiningXp = -1;
	private int currentMiningXp = 0;

	@Override
	protected void startUp()
	{
		rollingWindow = new RollingWindow(config.afkThresholdSeconds() * 1000L);
		miningGate = new MiningSuccessGate();
		loadAttempted = false;
		lastKnownPlayerKey = null;
		if (client.getGameState() == GameState.LOGGED_IN)
		{
			baselineMiningXp = client.getSkillExperience(Skill.MINING);
			currentMiningXp = baselineMiningXp;
			// If we're already logged in at plugin enable, attempt restore immediately.
			tryLoadPersistedSession();
		}
		else
		{
			baselineMiningXp = -1;
			currentMiningXp = 0;
		}
		overlayManager.add(overlay);
		log.debug("Mining Stats started");
	}

	@Override
	protected void shutDown()
	{
		// Persist before clearing state so the next startUp can recover it.
		persistCurrentSession();
		overlayManager.remove(overlay);
		rollingWindow = null;
		miningGate = null;
		baselineMiningXp = -1;
		currentMiningXp = 0;
		lastKnownPlayerKey = null;
		loadAttempted = false;
		log.debug("Mining Stats stopped");
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() != client.getLocalPlayer() || miningGate == null)
		{
			return;
		}
		int animId = client.getLocalPlayer().getAnimation();
		if (MiningAnimations.isMiningAnimation(animId))
		{
			miningGate.recordMiningAnimation(System.currentTimeMillis());
		}
	}

	/**
	 * Heartbeat for the gate's animation freshness. {@code AnimationChanged} fires only on
	 * animation-ID transitions; OSRS pickaxe animations frequently loop in-place during
	 * continuous mining without re-emitting an ID change. Without this poll the gate
	 * would close {@code DEFAULT_ANIMATION_GATE_MS} after the first swing's transition and
	 * stay closed despite continued swinging — leaving {@link #isCurrentlyMining()} false
	 * (no green title, ETA hidden) and starving yields landing outside that 3s window.
	 *
	 * <p>Polling per game tick (~600ms) refreshes the gate any time the player's current
	 * animation matches a mining animation. Mirrors the first-party {@code mining} plugin's
	 * tick-based detection pattern. Added in v0.3.2 in response to FlowersOEvil reporting
	 * that the title-color indicator never turned green during regular play.
	 */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (miningGate == null || client.getLocalPlayer() == null)
		{
			return;
		}
		handleAnimationHeartbeat(client.getLocalPlayer().getAnimation(), System.currentTimeMillis());
	}

	/**
	 * Plugin-layer seam for the per-tick animation heartbeat. Package-private so
	 * {@code PluginEventRoutingTest} can drive it with synthetic anim IDs without mocking
	 * {@link Client} or {@link net.runelite.api.Player}.
	 */
	void handleAnimationHeartbeat(int animId, long now)
	{
		if (miningGate == null)
		{
			return;
		}
		if (MiningAnimations.isMiningAnimation(animId))
		{
			miningGate.recordMiningAnimation(now);
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (miningGate == null || rollingWindow == null)
		{
			return;
		}
		int containerId = event.getContainerId();
		if (containerId != InventoryID.INVENTORY.getId())
		{
			return;
		}
		Map<Integer, Integer> current = countItems(event.getItemContainer());
		handleItemContainerEvent(containerId, current, System.currentTimeMillis());
	}

	/**
	 * Plugin-layer dispatch from a container event into the gate. Package-private so
	 * {@code PluginEventRoutingTest} can exercise this seam with synthetic inputs without
	 * needing to construct RuneLite {@link ItemContainerChanged} events or mock
	 * {@link ItemContainer}. The event-extraction shell ({@link #onItemContainerChanged})
	 * is behavior-preserving — same null guard, same container-ID filter, same dispatch.
	 *
	 * <p>v0.3.2 revert: only the inventory container is routed. The bank container path
	 * was removed after the Endless Harvest test on Leagues empirically demonstrated that
	 * direct-to-bank auto-deposit relics do not produce observable bank events while the
	 * bank UI is closed; the architecture's load-bearing assumption was false.
	 */
	void handleItemContainerEvent(int containerId, Map<Integer, Integer> current, long now)
	{
		if (miningGate == null || rollingWindow == null)
		{
			return;
		}
		if (containerId != InventoryID.INVENTORY.getId())
		{
			return;
		}
		List<Integer> gained = miningGate.onInventoryChange(current, now);
		for (int itemId : gained)
		{
			rollingWindow.recordEvent(itemId, now);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.MINING)
		{
			return;
		}
		int previousXp = currentMiningXp;
		currentMiningXp = event.getXp();
		if (baselineMiningXp == -1)
		{
			// First Mining StatChanged after startUp on a not-yet-logged-in client.
			baselineMiningXp = currentMiningXp;
			return;
		}
		if (currentMiningXp > previousXp && miningGate != null && rollingWindow != null)
		{
			long now = System.currentTimeMillis();
			List<Integer> gained = miningGate.onMiningXpDelta(now);
			for (int itemId : gained)
			{
				rollingWindow.recordEvent(itemId, now);
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGGED_IN)
		{
			if (baselineMiningXp == -1)
			{
				baselineMiningXp = client.getSkillExperience(Skill.MINING);
				currentMiningXp = baselineMiningXp;
			}
			handlePossibleCharacterSwitch();
			tryLoadPersistedSession();
		}
		else if (state == GameState.LOGIN_SCREEN
			|| state == GameState.HOPPING
			|| state == GameState.CONNECTION_LOST)
		{
			// Save before the disconnect blanks our state surface.
			persistCurrentSession();
			// Force re-baseline on the next inventory event so the post-login snapshot
			// doesn't get diffed against pre-logout state.
			if (miningGate != null)
			{
				miningGate.resetInventoryBaseline();
			}
		}
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!"miningstats".equals(event.getGroup()) || rollingWindow == null)
		{
			return;
		}
		if ("afkThresholdSeconds".equals(event.getKey()))
		{
			rollingWindow.setAfkThresholdMs(config.afkThresholdSeconds() * 1000L);
		}
	}

	/** Mining XP gained since the plugin was started. */
	public int sessionMiningXp()
	{
		return baselineMiningXp == -1 ? 0 : currentMiningXp - baselineMiningXp;
	}

	/** True if a mining animation has played within the gate's animation window. */
	public boolean isCurrentlyMining()
	{
		return miningGate != null && miningGate.isAnimationGateActive(System.currentTimeMillis());
	}

	/** Free inventory slots remaining, or -1 if the inventory container isn't currently available. */
	public int freeInventorySlots()
	{
		ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
		if (inv == null)
		{
			return -1;
		}
		int filled = 0;
		for (Item item : inv.getItems())
		{
			if (item.getId() > 0 && item.getQuantity() > 0)
			{
				filled++;
			}
		}
		return Math.max(0, InventoryEta.INVENTORY_CAPACITY - filled);
	}

	/**
	 * Display name for an item ID. Prefers the curated short name from {@link Ores}; falls
	 * back to the in-game item name via {@code ItemManager} for IDs not in the enum (Path B
	 * detection can record any item, not just enum members).
	 */
	public String displayNameFor(int itemId)
	{
		if (Ores.isOre(itemId))
		{
			return Ores.displayName(itemId);
		}
		try
		{
			String name = itemManager.getItemComposition(itemId).getName();
			if (name != null && !name.isEmpty() && !"null".equals(name))
			{
				return name;
			}
		}
		catch (RuntimeException ignored)
		{
			// Unknown item or cache miss — fall through to placeholder.
		}
		return "Item " + itemId;
	}

	/**
	 * Stable per-character ConfigManager key fragment. OSRS player names are alnum + spaces +
	 * underscores, max 12 chars; lowercase + whitespace→underscore yields a properties-safe
	 * fragment that survives display-capitalization changes.
	 */
	static String normalizePlayerName(String raw)
	{
		if (raw == null)
		{
			return null;
		}
		String trimmed = raw.trim();
		if (trimmed.isEmpty())
		{
			return null;
		}
		return trimmed.toLowerCase().replace(' ', '_');
	}

	private void captureLastKnownPlayerKey()
	{
		if (client.getLocalPlayer() == null)
		{
			return;
		}
		String key = normalizePlayerName(client.getLocalPlayer().getName());
		if (key != null)
		{
			lastKnownPlayerKey = key;
		}
	}

	/**
	 * Detect a character switch (Jagex-launcher hop or relog as a different character without
	 * fully restarting the client) and roll the in-memory window over to the new character.
	 *
	 * <p>Sequence: save current window under the OLD key, clear the window, update the key,
	 * reset the once-per-startup load flag so {@link #tryLoadPersistedSession} re-attempts for
	 * the new character.
	 *
	 * <p>If the local player isn't resolved yet, no-op — we'll re-check on the next event.
	 * If the key is unchanged (reconnect as same character), no-op — preserves any in-flight
	 * window state and avoids resetting the load flag prematurely.
	 */
	private void handlePossibleCharacterSwitch()
	{
		if (client.getLocalPlayer() == null)
		{
			return;
		}
		String currentKey = normalizePlayerName(client.getLocalPlayer().getName());
		if (currentKey == null || currentKey.equals(lastKnownPlayerKey))
		{
			return;
		}
		if (lastKnownPlayerKey != null && rollingWindow != null)
		{
			// Save departing character's stats under their key BEFORE swapping.
			persistCurrentSession();
			rollingWindow.clear();
		}
		lastKnownPlayerKey = currentKey;
		loadAttempted = false;
	}

	private void tryLoadPersistedSession()
	{
		if (loadAttempted || rollingWindow == null || configManager == null)
		{
			return;
		}
		// Player name flickers null around state transitions; only act once we have it stable.
		captureLastKnownPlayerKey();
		if (lastKnownPlayerKey == null)
		{
			return;
		}
		// Don't clobber an in-progress session — only restore if we're starting from zero.
		if (rollingWindow.totalCount() != 0)
		{
			loadAttempted = true;
			return;
		}
		String blob = configManager.getConfiguration("miningstats", PERSIST_KEY_PREFIX + lastKnownPlayerKey);
		Optional<RollingWindow.Snapshot> snap = SessionPersistence.parse(
			blob, System.currentTimeMillis(), SessionPersistence.DEFAULT_MAX_AGE_MS);
		if (snap.isPresent())
		{
			rollingWindow.restoreFromSnapshot(snap.get());
			log.debug("Mining Stats restored {} events for {}", snap.get().events.size(), lastKnownPlayerKey);
		}
		// Whether or not the load succeeded, mark attempted so we don't retry every LOGGED_IN.
		loadAttempted = true;
	}

	private void persistCurrentSession()
	{
		if (rollingWindow == null || configManager == null || lastKnownPlayerKey == null)
		{
			return;
		}
		RollingWindow.Snapshot snap = rollingWindow.exportSnapshot();
		String serialized = SessionPersistence.serialize(snap, System.currentTimeMillis());
		String key = PERSIST_KEY_PREFIX + lastKnownPlayerKey;
		if (serialized == null)
		{
			// Empty session — clear any stale persisted blob so a future login starts fresh.
			configManager.unsetConfiguration("miningstats", key);
		}
		else
		{
			configManager.setConfiguration("miningstats", key, serialized);
		}
	}

	private static Map<Integer, Integer> countItems(ItemContainer container)
	{
		Map<Integer, Integer> counts = new HashMap<>();
		if (container == null)
		{
			return counts;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() == -1)
			{
				continue;
			}
			counts.merge(item.getId(), item.getQuantity(), Integer::sum);
		}
		return counts;
	}

	@Provides
	MiningStatsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(MiningStatsConfig.class);
	}
}

package com.josiahcooper.miningstats;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("miningstats")
public interface MiningStatsConfig extends Config
{
	@ConfigItem(
		keyName = "windowMinutes",
		name = "Rolling window (min)",
		description = "Length of the rolling window over which the active rate is calculated."
	)
	@Range(min = 1, max = 30)
	default int windowMinutes()
	{
		return 5;
	}

	@ConfigItem(
		keyName = "afkThresholdSeconds",
		name = "AFK threshold (sec)",
		description = "Inactivity gap before mining is considered paused; gaps longer than this are excluded from the rate."
	)
	@Range(min = 10, max = 120)
	default int afkThresholdSeconds()
	{
		return 30;
	}

	@ConfigItem(
		keyName = "showPerOreBreakdown",
		name = "Show per-ore breakdown",
		description = "Display a table of each ore type, its session total, and its current rate."
	)
	default boolean showPerOreBreakdown()
	{
		return true;
	}

	@ConfigItem(
		keyName = "showInventoryETA",
		name = "Show inventory ETA",
		description = "Display an estimated time-to-full-inventory while actively mining."
	)
	default boolean showInventoryETA()
	{
		return true;
	}
}

package com.josiahcooper.miningstats;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

/**
 * Discriminator for "this item gain came from a mining swing."
 *
 * <p>Detection requires:
 * <ol>
 *   <li>A pickaxe-family animation has played within {@link #animationGateMs} (default 3000ms).</li>
 *   <li>A Mining XP delta has been observed within {@link #xpCoincidenceWindowMs} (default 1200ms,
 *       i.e. 2 game ticks) of the item-gain event.</li>
 *   <li>An inventory snapshot diff is non-negative for at least one item ID.</li>
 * </ol>
 *
 * <p>The animation gate is non-negotiable. It is what kills the Wintertodt brazier-repair
 * false-positive (Mining XP via hammer animation, not pickaxe), and the lamp/genie XP
 * scenarios. Quest XP grants apply post-dialog with no concurrent item-gain event in the
 * same window.
 *
 * <p>The coincidence window is symmetric: either the item-gain event or the XP delta may
 * arrive first. The class buffers a single item-source diff for up to
 * {@code xpCoincidenceWindowMs} waiting for an XP delta; symmetrically, an XP delta buffers
 * a timestamp waiting for an item-source event. On the second event of the pair, the buffer
 * is consumed (preventing double-counting against subsequent unrelated events).
 *
 * <p><strong>v0.3.2 revert:</strong> the v0.3.0 bank-handler architecture has been removed
 * after the Endless Harvest test on a Leagues alt empirically demonstrated that bank events
 * do not fire while the bank UI is closed. The architecture's load-bearing assumption — that
 * auto-deposit relics emit observable bank-positive deltas during continuous mining — was
 * false. Net effect: direct-to-bank auto-deposit relics (Endless Harvest and any future
 * equivalent) remain undetectable by this plugin. That is a Jagex-side architectural limit;
 * no amount of plugin cleverness on this surface can recover it without screen-scraping or
 * polling, which are out of scope.
 *
 * <p>Item-ID filtering is intentionally absent at this layer — the {@code Ores} enum is a
 * display-name override layer (handled at the plugin layer, not here). v0.3.2 introduces a
 * narrow blacklist for categorically-non-mining items inside {@link InventoryDelta}; that
 * filter sits upstream of this gate, so anything reaching {@code onInventoryChange} is
 * already a plausible mining yield by item-type.
 *
 * <p>This class is single-thread (RuneLite client thread). Not thread-safe.
 */
public final class MiningSuccessGate
{
	/** Default staleness allowance for the most recent pickaxe animation. */
	public static final long DEFAULT_ANIMATION_GATE_MS = 3000L;

	/** Default coincidence window between Mining XP delta and inventory increment (~2 game ticks). */
	public static final long DEFAULT_XP_COINCIDENCE_WINDOW_MS = 1200L;

	/**
	 * Sentinel for "no event of this kind has been seen yet." Using a finite negative rather
	 * than {@code Long.MIN_VALUE} avoids overflow in {@code now - sentinel} subtraction at
	 * test-scale timestamps; explicit equality checks cover unset state in production too.
	 */
	private static final long UNSET = -1L;

	private final long animationGateMs;
	private final long xpCoincidenceWindowMs;

	private long lastMiningAnimationMs = UNSET;
	private long lastMiningXpDeltaMs = UNSET;
	private Map<Integer, Integer> lastInventory = null;

	// Diff awaiting an XP-delta confirmation (item-event-first ordering).
	private List<Integer> heldDiff = null;
	private long heldDiffMs = UNSET;

	public MiningSuccessGate()
	{
		this(DEFAULT_ANIMATION_GATE_MS, DEFAULT_XP_COINCIDENCE_WINDOW_MS);
	}

	public MiningSuccessGate(long animationGateMs, long xpCoincidenceWindowMs)
	{
		this.animationGateMs = animationGateMs;
		this.xpCoincidenceWindowMs = xpCoincidenceWindowMs;
	}

	/** Mark a pickaxe-family animation as observed. */
	public void recordMiningAnimation(long now)
	{
		lastMiningAnimationMs = now;
	}

	/** True if a pickaxe-family animation played within {@link #animationGateMs}. */
	public boolean isAnimationGateActive(long now)
	{
		return lastMiningAnimationMs != UNSET && (now - lastMiningAnimationMs) <= animationGateMs;
	}

	private boolean xpDeltaWithinWindow(long now)
	{
		return lastMiningXpDeltaMs != UNSET && (now - lastMiningXpDeltaMs) <= xpCoincidenceWindowMs;
	}

	private boolean heldDiffWithinWindow(long now)
	{
		return heldDiff != null && heldDiffMs != UNSET && (now - heldDiffMs) <= xpCoincidenceWindowMs;
	}

	/**
	 * Reset the inventory baseline and any held diff. Called on login/hop/disconnect to
	 * prevent post-login snapshots from being diffed against pre-logout state.
	 */
	public void resetInventoryBaseline()
	{
		lastInventory = null;
		heldDiff = null;
		heldDiffMs = UNSET;
	}

	/**
	 * Consume an inventory snapshot.
	 *
	 * @return item IDs to record as mining successes (empty if the gate did not pair this
	 *         event with a recent XP delta, or if the animation gate is inactive, or if no
	 *         positive diff exists). Returns multiple entries when the diff covers a multi-unit
	 *         gain (e.g., +3 copper → three entries).
	 */
	public List<Integer> onInventoryChange(Map<Integer, Integer> current, long now)
	{
		if (lastInventory == null)
		{
			lastInventory = current;
			return Collections.emptyList();
		}

		// Discard any held diff that has aged past the coincidence window.
		if (heldDiff != null && !heldDiffWithinWindow(now))
		{
			heldDiff = null;
		}

		List<Integer> diff = InventoryDelta.itemsGained(lastInventory, current);
		lastInventory = current;

		if (diff.isEmpty())
		{
			return Collections.emptyList();
		}
		if (!isAnimationGateActive(now))
		{
			// Non-mining context — discard regardless of XP timing.
			return Collections.emptyList();
		}
		if (xpDeltaWithinWindow(now))
		{
			// XP delta is recent — pair this diff (plus any still-held earlier diff) with it
			// and consume the XP delta.
			lastMiningXpDeltaMs = UNSET;
			if (heldDiff != null)
			{
				List<Integer> merged = new ArrayList<>(heldDiff);
				merged.addAll(diff);
				heldDiff = null;
				return merged;
			}
			return diff;
		}
		// No recent XP delta — hold the diff for the XP delta to arrive. If a prior diff is
		// still held within window (back-to-back inventory events without an interleaved XP),
		// append rather than replace so the earlier swing isn't silently dropped. Keep the
		// older timestamp so the buffer still ages out conservatively.
		if (heldDiff != null)
		{
			heldDiff.addAll(diff);
		}
		else
		{
			heldDiff = new ArrayList<>(diff);
			heldDiffMs = now;
		}
		return Collections.emptyList();
	}

	/**
	 * Consume a Mining XP delta event.
	 *
	 * @return item IDs from a previously-held inventory diff if it pairs with this XP delta;
	 *         empty otherwise (in which case the XP delta is buffered for an inventory event).
	 */
	public List<Integer> onMiningXpDelta(long now)
	{
		if (heldDiffWithinWindow(now))
		{
			List<Integer> emit = heldDiff;
			heldDiff = null;
			// XP delta consumed by this pairing; do not also buffer it.
			lastMiningXpDeltaMs = UNSET;
			return emit;
		}
		// No pending diff — buffer the XP delta timestamp for an upcoming inventory event.
		lastMiningXpDeltaMs = now;
		return Collections.emptyList();
	}
}

package com.josiahcooper.miningstats;

import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import net.runelite.client.util.QuantityFormatter;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Map;

/**
 * Top-right panel rendering the SPEC's five lines: session XP, active rate, session total,
 * inventory ETA, and per-ore breakdown. Hidden when no mining activity falls within the
 * configured rolling window AND the player isn't currently swinging — keeps the overlay
 * off-screen during fishing/banking/idle, and disappears after a session naturally drains.
 *
 * <p>v0.2.0: title color is the activity indicator (green = actively mining, light gray =
 * stale/post-swing). With auto-hide, the three overlay states are now distinguishable at
 * a glance: hidden = correctly idle, green title = working, gray title = canary that
 * detection has stopped picking up swings.
 */
public class MiningStatsOverlay extends OverlayPanel
{
	private final MiningStatsPlugin plugin;
	private final MiningStatsConfig config;

	@Inject
	private MiningStatsOverlay(MiningStatsPlugin plugin, MiningStatsConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_RIGHT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		RollingWindow window = plugin.getRollingWindow();
		if (window == null)
		{
			return null;
		}

		long now = System.currentTimeMillis();
		long windowMs = config.windowMinutes() * 60_000L;

		// Auto-hide: suppress the panel when the player isn't mining now AND no events
		// remain inside the wall-clock rolling window. The pre-first-mine case (no events,
		// total == 0) is naturally subsumed; the post-session-drain case (mined earlier,
		// walked away, real time has elapsed past the window) is the intended behavior.
		//
		// v0.3.2: switched from `rate > 0` to a wall-clock event scan. Active-time freezes
		// at the AFK threshold, so the rate-based check stayed true forever after the
		// player walked away — the overlay never auto-hid in practice.
		boolean activelyMining = plugin.isCurrentlyMining();
		boolean hasRecentActivity = window.hasEventsWithinWallTime(windowMs, now);
		if (!activelyMining && !hasRecentActivity)
		{
			return null;
		}
		double rate = window.activeRatePerHour(windowMs, now);

		panelComponent.getChildren().clear();
		panelComponent.setPreferredSize(new Dimension(160, 0));

		// v0.2.0 indicator: title color is the canary for the three overlay states.
		//   GREEN — actively mining (visible + working).
		//   LIGHT_GRAY — visible because the rolling window still has events but no recent
		//     swing detected; either the player just stopped or detection has gone stale.
		// (The hidden-while-idle case is handled above by returning null.)
		Color titleColor = activelyMining ? new Color(108, 217, 108) : Color.LIGHT_GRAY;
		panelComponent.getChildren().add(TitleComponent.builder()
			.text("Mining Stats")
			.color(titleColor)
			.build());

		// Session XP — only show once XP has been accrued under the plugin.
		int xp = plugin.sessionMiningXp();
		if (xp > 0)
		{
			addLine("XP", QuantityFormatter.quantityToStackSize(xp));
		}

		// Active rate (events per hour over the configured window).
		addLine("Ores/hr", String.format("%,d", Math.round(rate)));

		// Session total.
		addLine("Total", String.format("%,d", window.totalCount()));

		// Inventory ETA — only when the player is actively mining and has free slots.
		if (config.showInventoryETA() && plugin.isCurrentlyMining())
		{
			int freeSlots = plugin.freeInventorySlots();
			if (freeSlots > 0)
			{
				long etaSeconds = InventoryEta.etaSeconds(freeSlots, rate);
				addLine("Full in", InventoryEta.formatEta(etaSeconds));
			}
		}

		// Per-ore breakdown.
		if (config.showPerOreBreakdown() && window.totalByOre().size() > 1)
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("————")
				.right("")
				.build());
			for (Map.Entry<Integer, Integer> entry : window.totalByOre().entrySet())
			{
				int oreId = entry.getKey();
				int oreTotal = entry.getValue();
				double oreRate = window.activeRatePerHour(oreId, windowMs, now);
				addLine(plugin.displayNameFor(oreId),
					String.format("%,d (%,d/h)", oreTotal, Math.round(oreRate)));
			}
		}

		return super.render(graphics);
	}

	private void addLine(String left, String right)
	{
		panelComponent.getChildren().add(LineComponent.builder()
			.left(left)
			.right(right)
			.build());
	}
}

package com.josiahcooper.miningstats;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Pure helper for computing positive item-quantity deltas between two inventory snapshots.
 *
 * <p>Decoupled from RuneLite's {@code ItemContainer} type so the diff math can be unit-tested
 * without mocking the client. The plugin's event handler converts {@code ItemContainer} into
 * a {@code Map<Integer, Integer>} of itemId → quantity and hands it here.
 *
 * <p>Negative deltas (drops, banking, trades) are ignored. Items appear once per unit gained,
 * so a +3 copper delta yields three entries.
 *
 * <p><strong>v0.3.2 contract:</strong> a curated blacklist of categorically-non-mining item
 * IDs is filtered out before the gain list is returned. This is a NEGATIVE filter — anything
 * not on the list still passes through, preserving v0.2.0's "future Jagex yield won't silently
 * zero-rate" property. The blacklist exists because OSRS Leagues coin-drop and smithing relics
 * empirically corrupted v0.3.1's Ores/hr math (~375k coins/hr counted as ores) and collapsed
 * inventory ETA to 0s. Excluded: coins, all furnace bars, uncut gems from mining, clue
 * geodes/scrolls. Whitelist (per-activity ore-item tables) is the semantically cleaner answer
 * but requires activity-detection plumbing — defer to v0.4.0+ if blacklist proves leaky.
 *
 * <p><strong>v0.3.2 revert:</strong> {@code hasNegativeDelta} was removed alongside the bank
 * handler. The manual-banking filter it served was load-bearing only for {@code onBankChange},
 * which v0.3.2 reverts after the Endless Harvest test on Leagues empirically confirmed
 * bank events do not fire while the bank UI is closed — the architecture's load-bearing
 * assumption was false.
 */
public final class InventoryDelta
{
	/**
	 * Item IDs that are inventory-additive but never mining yields. Verified against
	 * named identifiers below; numeric values are the canonical OSRS item IDs and will not
	 * change across RuneLite client versions.
	 *
	 * <p>If a future content drop introduces a new auto-add inventory item that should not
	 * count as ore (e.g., a new relic-driven bonus), append its ID here. The cost of a leaky
	 * blacklist is small bias on Total/Ores; the cost of a leaky whitelist is silently
	 * zero-rated new yields. The trade is intentional.
	 */
	private static final Set<Integer> YIELD_BLACKLIST = Collections.unmodifiableSet(new HashSet<>(Arrays.asList(
		// Currency
		995,    // Coins (Endless Harvest / coin-drop relic catastrophe — see v0.3.2 entry)

		// Smithing-relic bars (auto-smelted ore appears as bar, not ore)
		2349,   // Bronze bar
		2351,   // Iron bar
		2353,   // Steel bar
		2355,   // Silver bar
		2357,   // Gold bar
		2359,   // Mithril bar
		2361,   // Adamant bar
		2363,   // Rune bar

		// Uncut gems from random gem drops while mining
		1617,   // Uncut diamond
		1619,   // Uncut ruby
		1621,   // Uncut emerald
		1623,   // Uncut sapphire
		1631,   // Uncut dragonstone

		// Clue geodes (random drops while mining; reward-track item, not a yield)
		19887,  // Clue geode (easy)
		19888,  // Clue geode (medium)
		19889,  // Clue geode (hard)
		19891,  // Clue geode (elite)

		// Clue scrolls + scroll box (Leagues beginner-tier reward path)
		2677,   // Clue scroll (easy)
		2801,   // Clue scroll (medium)
		2722,   // Clue scroll (hard)
		12073,  // Clue scroll (elite)
		23182,  // Clue scroll (beginner)
		26739   // Scroll box (beginner)
	)));

	private InventoryDelta()
	{
	}

	/**
	 * Compute item-IDs gained between {@code before} and {@code after}, excluding entries
	 * matched by the v0.3.2 yield blacklist.
	 */
	public static List<Integer> itemsGained(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		List<Integer> gained = new ArrayList<>();
		for (Map.Entry<Integer, Integer> entry : after.entrySet())
		{
			int itemId = entry.getKey();
			if (YIELD_BLACKLIST.contains(itemId))
			{
				continue;
			}
			int delta = entry.getValue() - before.getOrDefault(itemId, 0);
			for (int i = 0; i < delta; i++)
			{
				gained.add(itemId);
			}
		}
		return gained;
	}

	/** Test-visible accessor for the blacklist contents. Package-private. */
	static Set<Integer> yieldBlacklist()
	{
		return YIELD_BLACKLIST;
	}
}

